window.GD = {"weaponTypes":[{"name":"Melee One-Handed","bonus":2,"zones":0,"only":["Empowered","Light","Throwing"],"text":"Melee One-Handed (Bonus +2, Distance: Same Zone): Empowered, Light, Throwing"},{"name":"Melee Two-Handed","bonus":4,"zones":0,"only":["Cleave","Heavy","Reach"],"text":"Melee Two-Handed (Bonus +4, Distance: Same Zone): Cleave, Heavy, Reach"},{"name":"Ranged One-Handed","bonus":1,"zones":1,"only":["Quick Draw"],"text":"Ranged One-Handed (Bonus +1, Distance: 1 Zone): Quick Draw"},{"name":"Ranged Two-Handed","bonus":3,"zones":1,"only":["Explosive","Suppression"],"text":"Ranged Two-Handed (Bonus +3, Distance: 1 Zone): Explosive, Suppression"}],"bannedRanged":["Parry","Berserker","Stalwart"],"bannedMelee":["Ricochet","Aimed Shot","Rapid Fire","Explosive","Pin Down","Suppression","Long Range","Close Quarters","Covering Fire"],"weaponMods":[{"name":"Accurate","text":"When Attacking with this weapon consider the enemies ER to be 2 less for a successful Attack. For instance if an enemy has an ER of 9 you would only need a 7, 8, or 9 to hit."},{"name":"Backlash","text":"If an Attack misses, make another free Attack with a -4 to its roll."},{"name":"Berserker","text":"Increases Damage by +1 for each consecutive hit but lowers ER by 1 each time. Resets if the user does not Attack for one round."},{"name":"Bliss","text":"Regenerates 3 Sanity at the end of each day."},{"name":"Bloodlust","text":"After killing an opponent, the user may make a free Attack against another opponent (once per turn)."},{"name":"Breaching","text":"Deals double Damage to objects and Constructs."},{"name":"Chained","text":"Regenerates 3 Stability at the end of each day."},{"name":"Master Craft","text":"Increase one of your Body Aspects by +1."},{"name":"Charging","text":"Adds +3 to charging rolls."},{"name":"Parry","text":"Increases Evasion Rating (ER) by +1."},{"name":"Cleave","text":"After hitting an enemy, you may choose to split the Damage between the original target and another in the same Zone. For the second target, you disregard ER and go straight to dealing Damage."},{"name":"Patient","text":"If no Attacks are made during a round, gain +4 to ER. The effect can stack up to a maximum of + 12, once an Attack is made the effect is removed."},{"name":"Close Quarters","text":"Adds +3 Damage when used in the same Zone as the targeted enemy."},{"name":"Covering Fire","text":"Allows a free Attack against an enemy when a friendly target is Attacked (once per round)."},{"name":"Covert","text":"Allows the user to attempt to hide after each Attack for free."},{"name":"Dash","text":"Allows the user to move and Attack as a single action."},{"name":"Dual Wield","text":"You may take an extra Attack action for free every turn."},{"name":"Elder","text":"Adds +1 to rolls for every 10 years the user is over 65."},{"name":"Empowered","text":"Changes Melee One-Handed Bonus to +3 instead of +2."},{"name":"Explosive","text":"Half of the weapon's Damage is dealt to everything in the same Zone."},{"name":"Foe Hater","text":"Grants +2 to Attack rolls against a specific enemy type (Monster Type must be selected when choosing this Modifier and cannot be changed.)"},{"name":"Glowing","text":"Allows this weapon to change the light level to Glow."},{"name":"Healing","text":"Regenerates 3 Health Damage at the end of each day."},{"name":"Heavy","text":"Deals an extra +2 Damage."},{"name":"Heirloom","text":"Adds +1 to rolls for each character who has passed this item on, starting at +1 if inherited through backstory, up to a maximum of +5."},{"name":"Historical","text":"Increase one of your Mind Aspects by +1."},{"name":"Holy","text":"Allow the use of the Faith Aspect for Attack rolls."},{"name":"Intimidating","text":"For each enemy killed during combat, the user may roll + Charisma against an enemy's CR to cause an opponent to surrender or flee."},{"name":"Leadership","text":"Adds +1 to Attacks for each ally in the same Zone(excluding the user)."},{"name":"Light","text":"Allows the use of Agility for melee Attack rolls instead of Strength."},{"name":"Long Range","text":"Increases the weapon's effective range by 1 Zone."},{"name":"Magic","text":"Allow the use of either Occult or Ancient Aspect for Attack rolls."},{"name":"Pin Down","text":"Restricts the target to 1 move action."},{"name":"Polytheistic","text":"Adds +1 to rolls for each patron the user is dedicated to."},{"name":"Precise","text":"Allows this weapon to cause a Critical hit on 11 or 12."},{"name":"Quick Draw","text":"Adds a virtual +3 to your speed for the purposes of determining an Agent’s order in a round."},{"name":"Rapid Fire","text":"Allows 5 Attacks in one round but limits the user to 1 action the following round. No other actions may be taken this turn except for Attacks."},{"name":"Reach","text":"Allows a free Attack once per round when an opponent enters the user's Zone."},{"name":"Retaliate","text":"After being Attacked, immediately make an Attack with your weapon, sacrificing 2 ER and 2 BR for the round."},{"name":"Ricochet","text":"Allows a second Attack at -3 to another target after the first Attack. This can be repeated until an Attack misses."},{"name":"Sacred","text":"Increase one of your Spirit Aspects by +1."},{"name":"Silent","text":"The weapon makes no noise when used, it gains +2 to Attacks while hiding and +2 to maintain Hiding after an Attack."},{"name":"Smokey","text":"Change light level in Zone to Shadow."},{"name":"Spell Bane","text":"Each successful Attack reduces that creature's words by 1."},{"name":"Stalwart","text":"Increases Body Resistance (BR) by +1."},{"name":"Suppression","text":"Reduces the target's BR by 1 for every Attack made. Once the target is hit, their BR resets to normal, and the cycle repeats. The user's Damage is reduced by 2 while using this weapon."},{"name":"Throwing","text":"Can be used as a one-handed ranged weapon. This weapon may have Modifiers from both the one-handed melee category and the one-handed ranged category."},{"name":"Void","text":"Damage from this weapon is not negated by Resistance Types."},{"name":"Wanted","text":"Mark a target at the start of your turn. Attacks against them are at +2 until killed. After the target is dead, select a new target."}],"weaponSpecialties":[{"name":"Block","text":"On a Critical hit, negate all Damage from the next Attack against you; if the Attack doesn't break through your BR, this effect will remain on your character until an Attack would actually Damage you."},{"name":"Crushing","text":"On a Critical hit, break a bone, applying the Crippled status."},{"name":"Deadly","text":"On a Critical hit, deal double Damage."},{"name":"Flaming","text":"On a Critical hit, apply the Burning status."},{"name":"Forceful","text":"On a Critical hit, move the target 1 Zone and inflict 5 additional Damage. This movement cannot be resisted."},{"name":"Frost","text":"On a Critical hit, apply the Frozen status."},{"name":"Harmony","text":"On a Critical hit, gain another action."},{"name":"Inspire","text":"On a Critical hit, all allies gain +2 to Attack and heal 1 Health, Sanity, and Spirit for 5 rounds."},{"name":"Lightning","text":"On a Critical hit, all opponents in the same Zone take half the Damage dealt to the original target."},{"name":"Poisonous","text":"On a Critical hit, apply the Poisoned status."},{"name":"Sharp","text":"On a Critical hit, apply the Bleed status."},{"name":"Stun","text":"On a Critical hit, enemies are on the back foot and stunned unable to take attack actions for 1 round."},{"name":"Sunder","text":"on a Critical hit, reduce the target's resistance types by 3."},{"name":"Vampiric","text":"On a Critical hit, instantly heal an amount equal to the Damage dealt."}],"armorTypes":[{"name":"Breezy","br":0,"er":3,"text":"Breezy (+0 BR, +3 ER): Offers minimal protection but maximizes evasion."},{"name":"Light","br":1,"er":2,"text":"Light (+1 BR, +2 ER): Strikes a balance between defense and mobility."},{"name":"Medium","br":2,"er":1,"text":"Medium (+2 BR, +1 ER): Provides stronger defense while still allowing for some mobility."},{"name":"Heavy","br":3,"er":0,"text":"Heavy (+3 BR, +0 ER): Offers maximum protection but at the cost of reduced evasion."}],"armorMods":[{"name":"Battery","text":"Increases Word Pool by 3."},{"name":"Bolstered","text":"Prevents movement by creatures of the same size or smaller unless moved by a spell."},{"name":"Cushioned","text":"Reduces fall Damage by half."},{"name":"Cat-Like","text":"Increases Agility by +1."},{"name":"Custom Fit","text":"Increase Evasion Rating (ER) by +1."},{"name":"Dense","text":"Increase Body Resistance (BR) by +1."},{"name":"Discreet","text":"Adds +1 to hiding attempts and makes it possible to wear the armor in public without drawing attention."},{"name":"Distinguished","text":"Increase Charisma by +1."},{"name":"Drenched In Magic","text":"Increase Occult, Faith, or Ancient by +1 (player's choice)."},{"name":"Heirloom","text":"Increase both BR and ER by +1 for each previous owner of the item (up to +5), starts with a +1 if characters include this item being passed down to them in their backstory. For the item to gain further bonuses the character would need to pass it to their next character."},{"name":"Hostile","text":"Counts as two people for Zone control purposes."},{"name":"Inscribed","text":"Increase Morality by +1."},{"name":"Large Pockets","text":"Increases storage capacity by +2."},{"name":"Magic Resistant","text":"Add your Resistance Type when taking Damage from a spell"},{"name":"Mind Shielded","text":"Increases Willpower by +1."},{"name":"Moddable","text":"Allows attachment of a weapon to the armor, freeing up inventory space and preventing disarmament. The weapon can still be used while attached and does not count towards inventory space while attached."},{"name":"Muscle Enhancement","text":"Increase Strength by +1."},{"name":"Neural Enhancement","text":"Increases IQ by +1."},{"name":"Recycled Blood","text":"Regenerate 1d6 of Health Damage taken after every combat instantly"},{"name":"Reflexive","text":"Increase Speed by +1."},{"name":"Slippery","text":"+4 to flee rolls"},{"name":"Spiked","text":"Prevents grappling unless the Attacker takes 6 Health Damage."}],"armorSpecialties":[{"name":"Blink","text":"Increase movement by +1 Zone."},{"name":"Built From Darkness","text":"Your Resistance Types now apply to Elemental Damage."},{"name":"Cannibal","text":"Each kill heals 2 Health."},{"name":"Enhanced Vision","text":"Choose either Dark Vision or Sun Sight."},{"name":"Iron Lungs","text":"No need to breathe."},{"name":"Juggernaut","text":"+4 BR"},{"name":"Junkie","text":"+4 to rolls when at half Health."},{"name":"Last Stand","text":"If an Attack would bring one of a character's Healing Pool to 0, you instead gain +5 Healing instantly in each Healing Pool. This effect is usable once per day."},{"name":"Mage Armor","text":"Add your armor's BR value to SR."},{"name":"Plot Armor","text":"Every time you gain a fate point, gain an additional one."},{"name":"Shielded by Faith","text":"Add your armor's BR value to MR."},{"name":"Stealth Armor","text":"Once a day, this Modifier makes it impossible to be seen for 1 hour out of combat or six rounds of combat. No rolls are needed when using this, and your hiding can't be broken."},{"name":"Torch Bearer","text":"Armor provides glow lighting in your Zone and, once a day, may shed blinding light in the same Zone and deal 15 Stability Damage to enemies."},{"name":"Weathered","text":"Unaffected by Weather Conditions."}],"wealth":[{"wc":1,"name":"Mundane","item":1,"housing":2,"transport":1,"bonus":1,"uses":1,"services":["Housekeeper","Taxi","Company","Guard"],"hStorage":2,"hGuests":0,"tStorage":1,"tZones":1,"text":["1 Spending Power for items/services.","2 Spending Power for acceptable housing.","1 Spending Power for acceptable transportation.","Item Bonus: +1 and may be used 1 time.","Services: (Housekeeper, Taxi, Company, Guard)","Housing: Rent a single bedroom or small living space (storage 2, no guests).","Transportation: Basic transportation (storage 1 item, movement 1 Zone)."]},{"wc":2,"name":"Quality","item":2,"housing":3,"transport":2,"bonus":2,"uses":2,"services":["Apprentice"],"hStorage":4,"hGuests":0,"tStorage":4,"tZones":2,"text":["2 Spending Power for items/services.","3 Spending Power for standard housing.","2 Spending Power for standard transportation.","Item Bonus: +2 and may be used 2 times.","Services: (Apprentice)","Housing: Rent a modest apartment (storage 4 items, no guests).","Transportation: Standard transportation (storage 4 items, movement 2 Zones)."]},{"wc":3,"name":"Advanced","item":3,"housing":4,"transport":2,"bonus":3,"uses":3,"services":["Spy","Doctor/Therapy","Trade Service"],"hStorage":8,"hGuests":1,"tStorage":4,"tZones":3,"text":["3 Spending Power for items/services.","4 Spending Power for modest housing.","2 Spending Power for modest transportation","Item Bonus: +3 and may be used 3 times.","Services: (Spy, Doctor/Therapy, Trade Service)","Housing: Rent a modest apartment (storage 8 items, 1 guest).","Transportation: Standard transportation (storage 4 items, movement 3 Zones)."]},{"wc":4,"name":"Luxury","item":5,"housing":6,"transport":4,"bonus":4,"uses":4,"services":["Occult Representative"],"hStorage":12,"hGuests":2,"tStorage":6,"tZones":4,"text":["5 Spending Power for luxury items/services.","6 Spending Power for luxury housing.","4 Spending Power for luxury transportation.","Item Bonus: +4 and may be used 4 times.","Services: (Occult Representative)","Housing: Modest House (storage 12 items, 2 guests).","Transportation: Luxury transportation (storage 6 items, movement 4 Zones)."]},{"wc":5,"name":"Exotic","item":6,"housing":8,"transport":5,"bonus":5,"uses":5,"services":[],"hStorage":16,"hGuests":3,"tStorage":8,"tZones":5,"text":["6 Spending Power for exotic items/services.","8 Spending Power for estate-level housing.","5 Spending Power for luxury transportation.","Item Bonus: +5 and may be used 5 times.","Services: None new.","Housing: Modest estate or large house (storage 16 items, 3 guests).","Transportation: Luxury transportation (storage 8 items, movement 5 Zones)."]}],"wealthNotes":{"overview":"Wealth in TBRPG is broken up into a few different categories, each representing an aspect of your character's finances, time, and energy spent acquiring something.","commit":"To use Spending Power, it must be committed; once committed, it can not be used on anything else. This will last the remainder of a mission, and once finished, Spending Power will be returned unless you wish to continue to commit. Depending on what you use your Spending Power on, it can result in different ways that a Commit is applied.","services":"A service that is committed will be usable during the mission it is committed to but can only be used the number of times that you committed it before they will deny service for the remainder of the mission.","oneTimeUse":"Things such as medicine, food, a couple of nails, or other mundane, situational, or single-use things fall into this category. A commit on something like this is committed once and the item remains for the mission, if it is a consumable then multiple commits must be made for each use of it. Once the mission ends if the item is not committed again it will disappear unless stated that you would rather it fall into Disrepair to keep for another time.","disrepairAndRuin":"Items and Housing are treated differently for the purposes of Committing; if they are not continuously committed, they will gain the status of Disrepair. Anything with this status is now unusable or in need of repair; you still have it, but until it is committed and fixed, it will not function. If an Item or Housing is left in this state for 3 continuous missions, it will gain the Ruined status and will be broken and removed from your possessions. This could be the item simply falling apart or being repossessed due to the lack of payments.","overCommitting":"Over-committing is a process in which you can insure an Item or Housing does not fall into Disrepair and instead will remain permanently. This process will need to be done over the course of 3 missions after that the asset is forever owned and will never need to be committed again.","wealthClass":"Wealth Class simply determines how expensive or hard something is to come by. Each Wealth Class comes with different benefits and advantages that may be applied to items, services, and housing/transportation.","itemBonus":"All items are given an Item Bonus based on the Wealth Class used to acquire them. These are one-time use bonuses; afterward, the item can still be used but will not provide its original bonus. Just like all things after a mission, Spending Power is returned, and you may choose to recommit an item to regain its bonus. These bonuses must be reasonable and within an item's limits since each item is unique and could have a plethora of uses such as rope being able to be used for climbing, grappling, securing a structure, or holding items together. This means that if a case can be made for an item gaining an Item Bonus, then it should be applied. For example, if you had a Quality bucket, you could use it to add +2 to help gather toxic chemicals from a hazardous area. It, however, could not help you shoot a Monster from 200 yards away. The bonuses must align with the item being used.","favors":"A Favor is a special type of Spending Power, it can be used as a voucher and will award a commit for free. A Wealth Class will be attached to the Favor upon receiving it depending on who gave it to you and the situation.","flavorQuote":"\"It was temporary, the apartment had 4 walls, a roof, and a place to sleep. It took some time to get it set up, with paperwork, fake names, and a bit of organization funding. But it would be ours for the job. Good thing it was temporary too, cause after patching Winston up the place was covered in blood, and I was really happy I wasn't responsible for cleaning up.\" - Arthur Blackwell, 1911 Argentina."},"services":[{"name":"Apprentice","text":"A follower or trainee in a profession related to the player. This service can only be Overcommitted; otherwise, an apprentice may not be taken. Upgrades increase their CR. Treat the apprentice as a base Human enemy CR Easy. If your character dies, you may continue as the apprentice, starting at level 2.","min":2},{"name":"Company","text":"Provides companionship, offering +3 recovery in each Healing Pool. They specialize in Healing both emotional and physical wounds. Upgrading this service increases the recovery by 1 + Wealth Class in each Healing Pool.","min":1},{"name":"Doctor","text":"Heals 10 Health, for each upgrade, increases Healing by +4. Upon upgrading to Wealth Class Luxury, the doctor may also treat injuries or disorders.","min":3},{"name":"Guard","text":"Assigned to protect a location or individual. Upgrading this service increases their effectiveness. Refer to the Guard entry in the Monsters section, and for each Wealth Class above Mundane, increase the Guard's difficulty by 1.","min":1},{"name":"Housekeeper","text":"Maintains your properties while you are away and can alert you to any occurrences. Upgrading this service above the Wealth Class Mundane will allow the housekeeper to prevent a number of items equal to 1 + Wealth Class of Housekeeper from gaining the Ruined Status.","min":1},{"name":"Occult Representative","text":"Provides insight into Beyond-related matters. This service may reveal a memory from a Beyond Artifact or two Modifiers of an enemy. Upgrading reveals one additional memory or Modifier.","min":4},{"name":"Spy","text":"Gathers information on a place or person. Roll CR 8 to obtain the desired information. Each Wealth Class above Advanced reduces the CR by 2. The GM may choose to refuse the information, offer an alternative, or create a mission based on the results.","min":3},{"name":"Taxi","text":"Transports you and your companions wherever they need to go. Upgrading this service past Wealth Class Mundane allows your Taxi to act as one other Mundane service. This effect is not compounded.","min":1},{"name":"Therapist","text":"Heals 10 Sanity; this Sanity, however, can be distributed between you and your Bonds if you invite a Bond to join you for a session. For each upgrade, allow an extra Bond to join you and increase Healing by +4. Upgrading to Wealth Class Luxury, the Therapist may also treat a Mental Disorder.","min":3},{"name":"Trade Service","text":"Covers tasks like construction, repairs, or metalwork. Custom jobs require these services instead of purchasing items. Unique agent armor or weapons need to be crafted by someone. Upgraded services allow for additional Modifiers +1 for each Wealth Class above Advanced. This +1 Modifier isn't restricted so any Modifier can be applied using this process.","min":3}],"housingMods":[{"name":"Aquatic","text":"Allows the property to function in water."},{"name":"Beyond Vault","text":"Prevents theft of stored items."},{"name":"Easy Escape","text":"The Flee action succeeds automatically in this location."},{"name":"Fast","text":"Increase Zone movement by 6. (This can apply to a house.)"},{"name":"Flying","text":"Enables vertical movement."},{"name":"Fortified","text":"Gain +2 In each Resistance Type and +5 in each Healing Pool."},{"name":"Free Food","text":"This property provides 8 food for each mission for the cost of 0 Spending Power. The food's Healing is equal to the Wealth Class of the Property."},{"name":"Guest Room","text":"Increase Guest capacity by +1."},{"name":"Guns","text":"Add a ranged weapon to this property."},{"name":"Hidden","text":"Remain undetectable by enemies."},{"name":"Medical Lab","text":"Creates 3 Medicines for each mission for the cost of 0 Spending Power. The medicine's Healing is equal to the Wealth Class of the property."},{"name":"Remote Controlled","text":"This property can be operated remotely."},{"name":"Trapped","text":"This property has a CR Medium Trap, which increases the number of traps."},{"name":"Warm Beds","text":"Characters resting here gain +2 extra Healing in each Healing Pool."},{"name":"Well Decorated","text":"Characters Gain +2 to Charisma Rolls while here."},{"name":"Well-Stocked","text":"Store an additional 12 items."}],"monsterCreation":{"intro":"Every adventure needs adversaries and that is where our Monsters come into play, from werewolves, to thugs, to hordes of zombies, to worms that eat subway cars; this section will explain how to create a Monster.","steps":[{"step":1,"title":"Choose a Type and a Difficulty","text":"The first step is to consider what type of Monster you are making, and there are multiple generic starting points to choose from. For example, the Undead type could be anything from a vampire, ghoul, or skeleton. However, if you wanted a ghost or possessed armor, you may want to go with Spirit or Golem. Whatever type you choose should reflect the idea you have and the mechanics you want. For instance, if you wanted to make a troll, you could pick Folklore to show its roots in mythology or local legends, or you could choose Beyond if it fits outside the norms of most trolls or simply want to design your own troll to be unique. After selecting a type, you will need to choose a Difficulty. Each Difficulty changes the CR, Aspects, how many Modifiers Monsters get, actions, and Healing Pools of all Monsters. So, depending on how challenging you want this encounter to be and possibly how many enemies you want in this fight, select a Difficulty appropriate for the Monster and its situation."},{"step":2,"title":"Select Modifiers and assign basic values","text":"The next step is to select Modifiers and assign some basic values. Each Monster starts with 1 Action and a Movement of 1 Zone. These values can be altered by the next step but are the base values for all Monsters. The next step is to choose Modifiers. Each Monster gets 3 Modifiers. These starting three are not affected by any additional Modifiers that come with a type, and they should still be given 3 Modifiers on top of that. The number of Modifiers can be adjusted due to Difficulty, and this should be done before choosing Modifiers. Now that you know how many Modifiers a Monster gets, it is time to choose some. There is a list of Monster Modifiers; however, a Monster can technically choose any Modifier it wants or even create new ones. The only limit is Legendary Modifiers, which should be reserved for Beyond Types or very legendary Monsters. After selecting the number of Modifiers allowed for your Monster, you are ready to move to the next step."},{"step":3,"title":"Assign Core Attribute Values and describe the Monster","text":"Now, the last step involves two things. First is assigning Core Attribute Values. Each Monster is given these values to start that may be adjusted by Difficulty, 1, 2, and 3. Choose a place for each value in either Mind, Body, or Spirit. These will be used to make rolls for the Monster when they attempt to use an Aspect. Instead of creating entire character sheets for Monsters, this allows them to streamline rolling and keep things simple. For example, a roll for Strength will be the number you assigned to Body. These values do not affect the Healing Pools of these Monsters in any way and are used for Aspect rolls only. (e.g., an Undead with a 1 Mind will roll an Investigation roll of +1). The second and last thing you need to do is make a description of your Monster. Describe its appearance, mannerisms, and maybe even some lore if you like. Whatever you choose to write about, it should give a good idea of what the Monster is. Once you do this, your Monster is finished and ready to terrorize your players."}],"custom_type_guidelines":{"intro":"For GMs who wish to make their own types, there are a couple of guidelines that should be followed but aren't necessary.","bullets":["All Healing Pools should be Increments of 5. This is for balance and keeps things clean.","There should be a theme to their type, meaning they should have strengths and weaknesses, as well as thought-out starting values. Possibly even custom starting Modifiers","It should also fill a gap; a lot of the Types that exist are pretty broad to encompass a lot of territory; if you make a type, it should fill an area that you believe needs an extra type and couldn't be slotted in somewhere else.","Lastly, add a short description to package it all up. After that, your type should be ready for use."]},"healing_for_monsters":{"text":"Just like characters, unless stated, Monsters only heal at the end of the day. So, if agents are able to wound a Monster and track it down at a later date, it may still be recovering from the previous fight. If a Monster has no ability to regain Healing Pools, it will instead recover a quarter of its Healing Pools each day."},"difficulty_rules":{"text":"Use CR (Challenge Rating) to determine the Difficulty of rolls against the Monster, such as for hiding or forceful movement. If a Modifier or CR would reduce a Monster's Healing Pool to 0, reduce the Healing Pool to 1. If a CR or Modifier would reduce a Resistance Type or Aspect below 0 keep it at 0. A Monster cannot have 0 in any Healing Pools upon creation or negative numbers in any of its Aspects or Resistance Types."},"cr_table":[{"name":"Easy","cr":7,"adjustments":{"Attack":"-1","All Resistance Types (BR, MR, SR)":"-1","Speed":"-1","Evade Rating (ER)":"-1","Healing Pool":"Reduce each by 5","Modifiers":"-1 Modifier","Core Stats":"-1 to all Core Stats"},"use_case":"Best for minions or hordes."},{"name":"Medium","cr":10,"adjustments":{"Attack":"No change (use base stats)","All Resistance Types (BR, MR, SR)":"No change (use base stats)","Speed":"No change (use base stats)","Evade Rating (ER)":"No change (use base stats)","Healing Pool":"No change (use base stats)","Modifiers":"No change (use base stats)","Core Stats":"No change (use base stats)"},"use_case":"For average encounters."},{"name":"Challenging","cr":14,"adjustments":{"Attack":"+2","All Resistance Types (BR, MR, SR)":"+2","Speed":"+2","Evade Rating (ER)":"+2","Healing Pool":"Increase each by 10","Modifiers":"+1 additional Modifier","Actions":"+1 Action","Core Stats":"+1 to all Core Stats"},"use_case":"For leaders or important figures/Monsters."},{"name":"Dangerous","cr":18,"adjustments":{"Attack":"+3","All Resistance Types (BR, MR, SR)":"+3","Speed":"+3","Evade Rating (ER)":"+3","Healing Pool":"Increase each by 25","Modifiers":"+2 additional Modifiers","Actions":"+2 Action","Core Stats":"+2 to all Core Stats"},"use_case":"Typically for formidable creatures, entities from The Beyond, or dangerous enemies."},{"name":"Hopeless","cr":20,"adjustments":{"Attack":"+5","All Resistance Types (BR, MR, SR)":"+5","Speed":"+5","Evade Rating (ER)":"+5","Healing Pool":"Increase each by 35","Modifiers":"+3 additional Modifiers","Actions":"+3 Action","Core Stats":"+4 to all Core Stats"},"use_case":"There is no hope here."}],"types":[{"name":"Beyond","description":"They exist beyond our understanding, creatures from another dimension where the rules don't apply. Their shapes, their intentions, everything about them defies explanation. They twist reality itself, and no matter what, you're never prepared to face them. Monsters from The Beyond are distinct and unique, not conforming to common tropes. For instance, a vampire could be The Beyond type, but it would need to be different from typical vampires, making it a special threat.","stats":{"Health":"?","Sanity":"?","Stability":"?","Attack":"+?","Evade Rating (ER)":"?","Body Resistance (BR)":"?","Mind Resistance (MR)":"?","Spirit Resistance (SR)":"?","Speed":"?","Starting Modifiers":"1 Legendary Modifier of choice"},"note":"(For every \"?\" simply implies that these values are entirely up to the GM and should be flavored according to the Monster being made.)"},{"name":"Construct","description":"They don't move, they don't think, they just exist. These are the chairs, doors, tables, and buildings. Mundane objects that have been brought into the world to serve their purpose without complaint or change.","stats":{"Health":"15","Sanity":"?","Stability":"?","Attack":"Not applicable","Evade Rating (ER)":"?","Body Resistance (BR)":"?","Mind Resistance (MR)":"?","Spirit Resistance (SR)":"?","Speed":"?","Starting Modifier":"Constructs do not receive Modifiers but can be adjusted for context."},"note":"(\"?\" simply implies that these values are entirely up to the GM and should be assigned appropriately for what the object is.)"},{"name":"Divine or Unholy","description":"They don't belong here, beings from planes far above or far below. Whether angelic or demonic, they follow a purpose too grand for mortal minds to grasp. Whatever they're here for, you can bet it won't be good.","stats":{"Health":"40","Sanity":"40","Stability":"40","Attack":"+6","Evade Rating (ER)":"14","Body Resistance (BR)":"+8 in each Resistance Type","Mind Resistance (MR)":"8","Spirit Resistance (SR)":"8","Speed":"3","Starting Modifiers":"1 Modifier of choice"}},{"name":"Feral","description":"They're just animals, plain and simple. Wolves, bears, or any creature of the wild. They're not evil or twisted; they're just surviving as nature intended. Cross their path, and you'll see the raw power of nature.","stats":{"Health":"30","Sanity":"20","Stability":"25","Size Adjustments":["Tiny/Small: +1 ER, -5 Health","Medium: No adjustment","Large: +1 BR, +5 Health, -1 ER, +1 Attack","Huge/Giant: +2 BR, -2 ER, +5 to each Healing Pool, +2 Attack"],"Attack":"+4","Evade Rating (ER)":"8","Body Resistance (BR)":"3","Mind Resistance (MR)":"1","Spirit Resistance (SR)":"1","Speed":"1 (+1 per size smaller than Large)","Starting Modifier":"None"}},{"name":"Folklore","description":"Legends come to life. People tell stories about them to scare children and entertain drunks, but when you're face-to-face with a troll, a dragon, or a walking myth, you realize that sometimes the stories don't do them justice.","stats":{"Health":"35","Sanity":"35","Stability":"35","Variable":"Add +5 to either Health, Sanity, or Stability based on character type (e.g., caster or brawler).","Attack":"+5","Evade Rating (ER)":"13","Body Resistance (BR)":"8","Mind Resistance (MR)":"6","Spirit Resistance (SR)":"6","Speed":"2","Starting Modifiers":"1 Modifier of choice"}},{"name":"Golem","description":"Nothing more than lifeless material until some fool breathes power into it. Then, it's an unstoppable machine driven by a single purpose. And it doesn't care what gets in the way.","stats":{"Health":"20","Sanity":"20","Stability":"20","Attack":"+3","Evade Rating (ER)":"5","Body Resistance (BR)":"15","Mind Resistance (MR)":"15","Spirit Resistance (SR)":"15","Speed":"0","Starting Modifier":"Statue (Resembles mundane objects and is considered lifeless or Hiding until it reveals itself.)"}},{"name":"Human","description":"Mortals, soft, breakable, and tragically overconfident. They've got just enough courage to stand against forces that will crush them. Not that they'll ever understand the futility of it.","stats":{"Health":"25","Sanity":"25","Stability":"25","Variable":"Add +5 to either Health, Sanity, or Stability based on character nature (e.g., caster or brawler).","Attack":"+3","Evade Rating (ER)":"7","Body Resistance (BR)":"3","Mind Resistance (MR)":"1","Spirit Resistance (SR)":"1","Speed":"1","Starting Modifier":"Speech"}},{"name":"Spirit","description":"Bound to the world through unfinished business or ancient curses. They drift, invisible to most, and torment those who cross their path. Sometimes, they just need closure. Other times, they want company in their misery.","stats":{"Health":"20","Sanity":"20","Stability":"30","Attack":"+3","Evade Rating (ER)":"11","Body Resistance (BR)":"10","Mind Resistance (MR)":"10","Spirit Resistance (SR)":"2","Speed":"0","Starting Modifier":"Possession"}},{"name":"Swarm","description":"On their own, these tiny things are laughable. But together? They become something else entirely. They're not here to fight; they're here to consume. And they'll keep going until there's nothing left.","stats":{"Health":"15","Sanity":"15","Stability":"15","Attack":"+0","Evade Rating (ER)":"10","Body Resistance (BR)":"2","Mind Resistance (MR)":"1","Spirit Resistance (SR)":"1","Speed":"2","Starting Modifier":"Swarm (Increase all Healing Pools by +5 and Attack by +1 for the number of Swarm in a Zone. This rule applies in reverse, so if a Swarm loses a Swarm in their Zone, they get -5 in all Healing Pools and - to Attack.)"}},{"name":"Undead","description":"Once alive, now just stubborn remnants of what was. They stumble through the world without care or thought, driven by hunger or hatred, depending on how fresh the curse is.","stats":{"Health":"30","Sanity":"25","Stability":"20","Variable":"Add +5 to either Health, Sanity, or Stability based on the type of undead (e.g., vampire, skeleton).","Attack":"+3","Evade Rating (ER)":"6","Body Resistance (BR)":"5","Mind Resistance (MR)":"4","Spirit Resistance (SR)":"0","Speed":"0","Starting Modifier":"Undeath"}}],"modifiers_in_general":{"text":"Modifiers are designed to be interchangeable. If you wish to apply a weapon Modifier to a Monster or vice versa, you can, though the final decision lies with the GM. GMs are encouraged to create and add their own Modifiers, which promote customization. This system is intended to foster creativity, allowing for the introduction of new Modifiers to add unpredictability and depth to both items and creatures."}},"monsterMods":[{"name":"Aquatic","text":"Movement 2 Zones in the water. This Modifier can be taken more than once, increasing movement by 2 Zones in water each time.","tier":"common"},{"name":"Aura of Damage","text":"Choose a Damage Type and deal 2 Damage every round to all enemies in the same Zone. No Resistance Types are allowed to negate this Damage. This Modifier can be taken more than once, increasing the Damage by +2 each time it is taken.","tier":"common"},{"name":"Aura of Healing","text":"All allies in the same Zone gain +2 Healing in each Healing Pool instantly. This Modifier can be taken more than once, increasing Healing by +5 each time it is taken.","tier":"common"},{"name":"Beyond Touched","text":"Exchange a Modifier for a legendary Modifier.","tier":"common"},{"name":"Blind Sight","text":"Gains Blind Sight.","tier":"common"},{"name":"Bloodthirsty","text":"Heals 5 Health for Damage dealt to an enemy. This Modifier can be taken more than once, increasing the Healing by 5 each time.","tier":"common"},{"name":"Boneless","text":"Can fit into spaces two sizes smaller than it. This also allows the Constricted Spaces Zone Modifier to be negated for this entity.","tier":"common"},{"name":"Brain Food","text":"Heals missing Sanity for Damage dealt to an enemy. This Modifier can be taken more than once, increasing the Healing by 5 each time.","tier":"common"},{"name":"Caster","text":"Give this enemy 5 words and a potency of 1. This Modifier can be taken more than once, increasing the words by 5 and potency by 1 each time.","tier":"common"},{"name":"Disguised","text":"Can change its form to look like someone else, requiring a Difficulty Challenge for anyone to see through its disguise.","tier":"common"},{"name":"Elemental","text":"Damage type is changed to Elemental.","tier":"common"},{"name":"Elusive","text":"May take the Hiding action after moving for free.","tier":"common"},{"name":"Ethereal","text":"Can Move through solid objects. This includes moving through non-connected Zones.","tier":"common"},{"name":"Explosive","text":"Attacks Damage everyone in a Zone, including allies.","tier":"common"},{"name":"Flying","text":"May move 2 Zones Vertically. This Modifier can be taken more than once, increasing Zone movement vertically by 2 each time.","tier":"common"},{"name":"Large","text":"(Increase Size by 1, may be chosen multiple times)","tier":"common"},{"name":"Leader","text":"For each nearby ally, increase all Resistance Types by +1 to a maximum of +4.","tier":"common"},{"name":"Mimic","text":"Can change its form to look like an object, requiring a Difficulty Challenge for anyone to see through its disguise.","tier":"common"},{"name":"Mutant","text":"You may exchange this Modifier for another on this list at any time, but reduce the number of Modifiers this entity is allowed to have by 1. It can be selected more than once.","tier":"common"},{"name":"Nimble","text":"Increase ER by +2. This Modifier can be taken more than once, increasing ER by +2 each time.","tier":"common"},{"name":"Occult","text":"Damage type is changed to Stability.","tier":"common"},{"name":"Possession","text":"Possession can possess objects or people that are close; an attempt to possess someone requires a roll + Attack bonus against the target's roll + Morality. If it succeeds, that character is now. Controlled by this entity for 3 rounds)","tier":"common"},{"name":"Psychological Attacks","text":"Damage type is changed to Sanity.","tier":"common"},{"name":"Quick","text":"Change Movement to 2 Zones and add +3 to Speed. This Modifier can be taken more than once, increasing Zone movement by +1 and Speed by +3 each time.","tier":"common"},{"name":"Rage","text":"Increase Damage +5 but reduce its Resistance Types to 0.","tier":"common"},{"name":"Ranged","text":"May Attack from 2 Zones away Damage is decreased by 2.","tier":"common"},{"name":"Reach","text":"May Attack once per turn at an enemy that enters its space.","tier":"common"},{"name":"Shade","text":"Increase all Resistance Types by +2 if in shadows, and gain Dark Vision.","tier":"common"},{"name":"Small","text":"(Decrease Size by 1, may be chosen multiple times)","tier":"common"},{"name":"Soul Feed","text":"Heals missing Stability for Damage dealt to an enemy. This Modifier can be taken more than once, increasing the Healing by 5 each time.","tier":"common"},{"name":"Speech","text":"Can Speak.","tier":"common"},{"name":"Steel Mind","text":"Increase MR by +2; this Modifier can be taken more than once, increasing MR by +2 each time.","tier":"common"},{"name":"Sun Born","text":"Increase all Resistance Types by +2 if in light, and gain Sun Sight.","tier":"common"},{"name":"Tanky","text":"Gain + 5 in each Healing Pool; this Modifier may be taken more than once, increasing each Healing Pool by +5 each time.","tier":"common"},{"name":"Thick Skin","text":"Increase BR by +2; this Modifier can be taken more than once, increasing BR by +2 each time.","tier":"common"},{"name":"Toxic","text":"Apply a status effect on crit. This Modifier may be chosen more than once, allowing an extra status effect each time.","tier":"common"},{"name":"Undeath","text":"When this creature would normally die, instead roll d6 if it is 4 or higher the creature regains 10 Healing in the affected Healing Pool. If this would result in a higher Healing Pool than the Monster began with, instead just simply reset it to its starting value.","tier":"common"},{"name":"Ungodly","text":"+4 Stability Damage; this Modifier can be taken more than once, increasing Damage by +4 each time.","tier":"common"},{"name":"Unimaginable Horror","text":"+4 Sanity Damage; this Modifier can be taken more than once, increasing Damage by +4 each time.","tier":"common"},{"name":"Unshakable Faith","text":"Increase SR by +2; this Modifier can be taken more than once, increasing SR by +2 each time.","tier":"common"},{"name":"Vengeful","text":"Can do 2 actions instead of 1.","tier":"common"},{"name":"Vicious","text":"+4 Health Damage; this Modifier can be taken more than once, increasing Damage by +4 each time.","tier":"common"},{"name":"Born from the Depths","text":"Has constant Pitch lighting in 2 Zones around it.","tier":"legendary"},{"name":"Deadly","text":"Select a Status effect, which is applied every time this entity makes an Attack.","tier":"legendary"},{"name":"Death Mark","text":"If the players don't defeat this enemy in a certain time they must all make Death Die rolls, the time is chosen by the GM and should allow the players time to defeat the Monster but put pressure on them.","tier":"legendary"},{"name":"Fated","text":"Gains +1 Fate point each round.","tier":"legendary"},{"name":"God-Like","text":"Increase all Healing Pools by 15 and all Resistance Types by 5.","tier":"legendary"},{"name":"Godspeed","text":"Movement starts at 3 Zones.","tier":"legendary"},{"name":"Hijack","text":"Possession, but it happens automatically.","tier":"legendary"},{"name":"Multi-Limbed","text":"Starts with 3 actions.","tier":"legendary"},{"name":"Nightmare","text":"Causes Terrified status to all enemies in a range of 2 Zones constantly.","tier":"legendary"},{"name":"Radiance","text":"Has Constant Blinding lighting in 2 Zones around it.","tier":"legendary"},{"name":"Swallow","text":"When Attacking an entity they may choose, on a successful Attack, to swallow the entity instead. A CR of Challenging Strength is required to get free, if the entity fails 4 times they are eaten and now dead.","tier":"legendary"},{"name":"Void","text":"Change Damage Type to Corrupted.","tier":"legendary"}],"monsterExamples":[{"name":"Carrion Feaster","type":"Undead","difficulty":"Easy","cr":7,"type_line":"Undead, Easy (CR 7)","core":{"body":2,"mind":0,"spirit":1},"health":25,"sanity":20,"stability":15,"attack":2,"er":5,"br":6,"mr":3,"sr":0,"speed":-1,"actions":null,"mods":[{"name":"Undeath","text":"On a roll of 4 or higher on a d6, the regains 10 Health if it drops to 0."},{"name":"Bloodthirsty","text":"Heals missing Health equal to the Damage dealt instantly."},{"name":"Thick Skin","text":"+2 to Body Resistance."}],"text":"Once a living soul, now reduced to a grotesque, shambling mass, the Carrion Feaster roams graveyards and battlefields alike, drawn to the scent of decay. Its hunger knows no end. The more it feasts, the stronger it becomes; its tough hide is a testament to the life it no longer has. And just when you think you've put it down, it rises again, ready to gorge on flesh once more."},{"name":"Guard","type":"Human","difficulty":"Easy","cr":7,"type_line":"Human, Easy (CR 7)","core":{"body":2,"mind":1,"spirit":3},"health":20,"sanity":15,"stability":15,"attack":2,"er":6,"br":1,"mr":0,"sr":0,"speed":0,"actions":null,"mods":[{"name":"Speech","text":"Allows the enemy to speak."},{"name":"Ranged","text":"Allows Attacks from 2 Zones away but decreases Damage by 2."},{"name":"Quick Draw","text":"Adds a virtual +3 to your speed for the purposes of determining the monster’s order in a round. (This is an example of a monster using a modifier from another table, in this instance from the weapon modifiers.)"}],"text":"The Guard is a familiar sight, steadfast, armed, and ever-alert. Whether he's there to protect or to block your path depends entirely on your intentions. With a sharp eye and a quicker hand, he's not just standing idly by; he's ready to spring into action!"},{"name":"Haunted Mirror","type":"Construct","difficulty":"Medium","cr":10,"type_line":"Construct, Medium (CR 10)","core":{"body":3,"mind":1,"spirit":2},"health":15,"sanity":15,"stability":15,"attack":0,"er":0,"br":5,"mr":4,"sr":4,"speed":0,"actions":null,"mods":[{"name":"Possession","text":"Allows the mirror to possess the reflection of whoever gazes into it."},{"name":"Reflection Trap","text":"The target must make a CR 8 Mind roll. On a failure, they are trapped in a mirrored version of reality for 1d6 rounds, during which time they take 1 Sanity and Stability Damage and only get 1 action each round. They may still Attack the mirror from inside and, if broken, may escape early."},{"name":"Curse","text":"Inflicts a debilitating curse, causing the target to suffer -2 to all rolls while the mirror remains unbroken."}],"text":"A seemingly ordinary mirror with an extraordinary curse. Those foolish enough to stare too long into its surface risk much more than just vanity. Their reflection, once caught, is dragged into a twisted, mirrored reality, leaving their body behind as little more than a puppet. Trapped inside, they face horrors designed to break their spirit, and unless they shatter the curse, their reflection might just be the only part of them that ever leaves."},{"name":"Holy Messenger","type":"Divine or Unholy","difficulty":"Medium","cr":10,"type_line":"Divine or Unholy, Medium (CR 10)","core":{"body":2,"mind":2,"spirit":3},"health":40,"sanity":40,"stability":40,"attack":6,"er":14,"br":6,"mr":8,"sr":8,"speed":3,"actions":null,"mods":[{"name":"Aura of Light","text":"Restores 2 Health to all allies instantly in the same Zone every round."},{"name":"Divine Shield","text":"Grants +2 MR to all nearby allies."},{"name":"Holy Smite","text":"Deals +3 Elemental Damage to enemies of the Unholy or Undead."}],"text":"The Holy Messenger walks the line between the divine and the mortal, radiant with an otherworldly light that heals the righteous and punishes the wicked. Its very presence bolsters those who fight for justice, while its enemies feel the weight of divine judgment in every blow. With each step, the Messenger shields its allies and strikes down the corrupt with the full fury of the heavens, ever faithful to its sacred mission."},{"name":"Jingle Bells","type":"Beyond","difficulty":"Dangerous","cr":18,"type_line":"Beyond, Dangerous (CR 18)","core":{"body":3,"mind":2,"spirit":1},"health":55,"sanity":60,"stability":50,"attack":7,"er":16,"br":12,"mr":12,"sr":8,"speed":5,"actions":2,"mods":[{"name":"Nightmare Presence","text":"Jingle Bells is counted as hiding at all times, the only way to Attack him is to roll a 1d6 before each Attack, on a number higher than 3 you are able to pinpoint his location and make your Attack. Fail this roll and your Attack action is wasted."},{"name":"Terrorizing Laugh","text":"At the start of each round, Jingle Bells releases a chilling laugh. All enemies in the same Zone suffer 2 points of Sanity Damage regardless of resistance."},{"name":"Shadow Strike","text":"Jingle Bells can Attack from any shadow in his Zone, ignoring ER and Resistance Types, this is a free action and takes place every round that a target is in an area of shadow."},{"name":"My Bells!","text":"Each time Jingle Bells is injured, he loses a bell, and the number needed to spot him is reduced by 1."},{"name":"Unseen Terror","text":"On a successful hit, the target takes 2 Corrupted Damage in each Healing Pool."}],"text":"Jingle Bells is a twisted entity from The Beyond, manifesting as an eerie clown that only appears at night. Those who encounter him never see his true form, only his long shadowy creeping along the walls, the haunting sound of his laughter, and the unsettling jingle of his many bells. He thrives in dark, striking fear into the hearts of those he decides to make his midnight playmates."},{"name":"Rat Swarm","type":"Swarm","difficulty":"Medium","cr":10,"type_line":"Swarm, Medium (CR 10)","core":{"body":1,"mind":2,"spirit":3},"health":20,"sanity":15,"stability":20,"attack":3,"er":10,"br":2,"mr":1,"sr":1,"speed":3,"actions":null,"mods":[{"name":"Swarm","text":"Increases all Healing Pools by +5 and Attack by +1 for the number of Swarm in a Zone. This rule applies in reverse, so if a Swarm loses a member in their Zone, they get -5 in all Healing Pools and -1 to Attack."},{"name":"Toxic","text":"Inflicts Disease on Critical."},{"name":"Quick","text":"Adds +3 to Speed."}],"text":"A Rat Swarm is a living tide of vermin, overwhelming their prey not by force but by sheer numbers. Their bites are quick and infectious, spreading disease as they gnaw away at whatever stands in their path. Each rat alone is a nuisance, but together, they are a nightmare, a relentless mass that leaves behind only sickness and ruin. Try to scatter them if you can, but know that where there is one, there are always more lurking in the shadows."},{"name":"Rabid Wolf","type":"Feral","difficulty":"Medium","cr":10,"size":"Huge","type_line":"Feral, Medium (CR 10), Huge","core":{"body":3,"mind":1,"spirit":2},"health":35,"sanity":20,"stability":25,"attack":6,"er":6,"br":7,"mr":0,"sr":0,"speed":1,"actions":null,"mods":[{"name":"Large","text":"Increases Size by 1."},{"name":"Thick Skin","text":"+2 to Body Resistance."},{"name":"Rage","text":"+5 to Damage, but reduces all Resistance Types to 0."}],"text":"The Rabid Wolf is a force of raw, untamed fury, prowling the wilds with only one thought in its shattered mind, kill. Its disease has warped both its body and soul, making it larger, stronger, and infinitely more dangerous than any of its kin. With thick skin and a reckless bloodlust, this beast is at its most deadly when cornered. But be warned, its uncontrollable rage leaves it vulnerable, though even a dying wolf is still a wolf to be feared."},{"name":"Troll","type":"Folklore","difficulty":"Challenging","cr":14,"type_line":"Folklore, Challenging (CR 14)","core":{"body":4,"mind":2,"spirit":3},"health":50,"sanity":45,"stability":45,"attack":7,"er":15,"br":12,"mr":8,"sr":8,"speed":4,"actions":null,"mods":[{"name":"Regeneration","text":"Restores 5 Health at the start of its turn."},{"name":"Thick Skin","text":"+2 to Body Resistance."},{"name":"Vicious","text":"Increases Health Damage by +4."},{"name":"Explosive","text":"Attacks Damage everyone in a Zone, including allies."}],"text":"A Troll is the embodiment of brute force and rage, with a hide as tough as stone and a temper to match. Wounds that should slow it down heal almost instantly, and when it strikes, it's not just its target that feels the blow, everything in its vicinity suffers. The Troll's blind fury turns its every Attack into a chaotic outburst, with little regard for who or what gets caught in the carnage. When it's enraged, there's no reasoning with it, only surviving."},{"name":"The Unfinished Doll","type":"Golem","difficulty":"Medium","cr":10,"type_line":"Golem, Medium (CR 10)","core":{"body":3,"mind":1,"spirit":2},"health":30,"sanity":30,"stability":30,"attack":3,"er":5,"br":15,"mr":15,"sr":15,"speed":0,"actions":null,"mods":[{"name":"Statue","text":"It resembles mundane objects and is considered lifeless or Hiding until it reveals itself."},{"name":"Elusive","text":"May take the Hiding action after moving for free."},{"name":"Mimic (CR 7)","text":"Can change its form to look like an object, requiring a Difficulty Challenge for anyone to see through its disguise."},{"name":"Reach","text":"May Attack once per turn at an enemy that enters its space."}],"text":"A large wooden figure with adjustable appendages. Once inanimate, it is now filled with a desire to play, it enjoys jumping out and tackling people, but it's a very heavy solid wooden construct and often crushes those it plays with. It has lost many friends this way, but there are always new friends to make."},{"name":"Wisp","type":"Spirit","difficulty":"Medium","cr":10,"type_line":"Spirit, Medium (CR 10)","core":{"body":1,"mind":2,"spirit":3},"health":20,"sanity":20,"stability":30,"attack":3,"er":11,"br":10,"mr":10,"sr":2,"speed":3,"actions":null,"mods":[{"name":"Possession","text":"Allows the enemy to possess nearby objects or people."},{"name":"Ethereal","text":"Allows the enemy to move through solid objects."},{"name":"Shade","text":"Increases all Resistance Types by +2 when in shadows."},{"name":"Quick","text":"Changes Movement to 2 Zones and adds +3 to Speed."}],"text":"The Wisp is more than just a flickering light in the dark, it's a trickster, a phantom that plays with the minds of those unlucky enough to follow its glow. It drifts silently through the night, luring victims deeper into the unknown. Walls and barriers mean nothing to it, and when shadows fall, its Strength only grows. To battle a Wisp is to fight a ghost, always one step ahead, always just out of reach."}],"artifactCreation":{"steps":[{"n":1,"title":"The idea (who owned it and why)","text":"The first step is the idea itself and why. Beyond Artifacts are always something owned by someone. They are objects left behind by those who had been Tethered by The Beyond and are no longer on this mortal plane. Because these items have been corrupted by exposure to The Beyond and had connections to those individuals they retain some of their memories. They create a copy of that person's psyche and embed it in the object itself. So, after establishing who owned it, what happened to them, and how their experience may have altered the item, it is time to move to the next step."},{"n":2,"title":"Mechanics (Modifier + Debuff + optional rules)","text":"In this step, you will decide how the object acts mechanically; there are no specific guidelines for this section because there are no rules for these items. Each Beyond Artifact is unique and ranges in power drastically. However, there is one constant among all of the Artifacts: they have a positive and a negative. Each Artifact comes with a good Modifier; this can be anything from the +5 to Attacks and Damage that only Beyond Artifacts can have, granting the ability to fly or shoot lightning from your fingertips. Then comes the negative debuff, all of these items are cursed in some way and must be accompanied by a negative effect. These can range from tame to absolutely dreadful, from losing Health every time you activate it to losing your very soul if you roll poorly. This is the essence of these dark Artifacts; each Modifer should be unique and treated differently. So now, after considering this, it is time to add Modifiers to your mechanics, add a bonus Modifier, add a negative Debuff, and a few rules if you desire; as stated before, there is no concrete way to make an Artifact as long as it follows the Modifier, Debuff rule."},{"n":3,"title":"Memories (exactly 5)","text":"Now that we have established who owned this item, what happened to them, what the item does, and how that individual influenced how the Artifact operates, you can now craft your Memories. A memory is two things: one, a piece of lore to help tie your item to the world, and two, a mechanical benefit if characters pursue the object's history. There should only ever be 5 Memories. However, each memory can contain as much or as little information as you'd like; it can be a novel or a single sentence. No matter what you decide, though, the memory should give a good narrative of the item; by the end of all the Memories, each item should give the players a sense of intimacy. They should know that item in and out and the person who last held it."}],"closing":"With the last three steps completed, you are now finished and ready to add all sorts of horrific and powerful items to your game.","intro_to_creation":"CREATING A BEYOND ARTIFACT While the list below will provide a few Artifacts, it is important for a GM to feel comfortable creating their own as well. This section will explain how a Beyond Artifact is crafted.","tables":[{"name":"Memories of the Beyond","rows":[{"memory":1,"cr":"Easy","reward":"Learn Quote 1"},{"memory":2,"cr":"Medium","reward":"Learn Quote 2"},{"memory":3,"cr":"Challenging","reward":"Learn Quote 3 and gain 1 Fate Point"},{"memory":4,"cr":"Dangerous","reward":"Learn Quote 4 and gain 1 Fate Point"},{"memory":5,"cr":"Dangerous","reward":"Remove the item's negative effect, learn Quote 5, and gain the ability to speak freely with the item's previous owner."}]},{"name":"Noticed (The Beyond Always Listens)","rows":[{"noticed":"1-5","effect":"The world seems to be watching, permanently reducing your Sanity by 1 for each point."},{"noticed":"6-10","effect":"You feel The Beyond tugging at you, permanently reducing Stability by 1 for each point."},{"noticed":"11+","effect":"The Beyond seeks to claim you. For each point above 10, roll 2d6 + your highest Aspect to remain connected to the world by what you value most. Failure results in your character being pulled into The Beyond, never to be seen again","author_note_verbatim":"I want this changed to the following and maybe mentioned earlier rather than the end of the book as well. \"The Beyond seeks to use you as a gateway for something terrible. For each point above 10, roll 2d6 + your highest Aspect to keep it from opening your mind. Failure results in your character manifesting a Beyond Event whether that is a Beyond Entity or Rupture. They have been turned into another conduit for The Beyond to leak into our world."}]}],"cost_limits":{"attack_bonus":"All Beyond Artifact weapons start with a + 5 bonus to Attacks, a value exclusive to these items.","modifiers":"all Beyond Artifacts come with unique Modifiers and may permit the choice of others.","required_structure":"they have a positive and a negative. Each Artifact comes with a good Modifier ... Then comes the negative debuff, all of these items are cursed in some way and must be accompanied by a negative effect.","memory_count":"There should only ever be 5 Memories.","history_roll":"The player rolls using Occult, Faith, Ancient, or IQ to learn these facts. Failure results in gaining 1 point of Noticed.","acquisition":"These Artifacts can be acquired either through a mission or by gaining a level.","balance":"As objects of immense power, they are intentionally unbalanced.","numeric_cost":null},"notes":{"overview":"BEYOND ARTIFACTS: THE STRONGEST TOOLS IN THE DARK Beyond Artifacts are items imbued with special powers from The Beyond. These could range from a teacup with the ability to taste like anything to a sword that talks and drinks blood. The possibilities are limitless, and no two Artifacts should ever be alike. These items could hold historical significance or even be the source of power for a cult or a Beyond Monster. As objects of immense power, they are intentionally unbalanced. These Artifacts can be acquired either through a mission or by gaining a level. In the latter case, the character mentally breaks through The Beyond, pulling something from the other side, typically in a dream, after which the item appears upon waking. All Beyond Artifact weapons start with a + 5 bonus to Attacks, a value exclusive to these items. Additionally, all Beyond Artifacts come with unique Modifiers and may permit the choice of others.","deeper_connection":"A DEEPER CONNECTION A person may attempt to learn an artifact's history by connecting through The Beyond. This dangerous process, performed during sleep when the mind is closest to The Beyond, can yield great rewards. Each Artifact holds five pieces of history, akin to fragmented memories embedded in the item. The player rolls using Occult, Faith, Ancient, or IQ to learn these facts. Failure results in gaining 1 point of Noticed. Players are advised not to read these histories ahead of time, but instead to uncover them during gameplay. If an item has been heavily used, or if desired, the GM can change the memories to new ones, ensuring there's always something new to discover about Artifacts.","beyond_conversations":"BEYOND CONVERSATIONS If a character gains the ability to speak freely through The Beyond, they can ask questions that the item's previous owner might answer based on their experiences and time period. The GM has discretion over these interactions to ensure they add flavor without breaking the game."}},"artifacts":[{"name":"BLOOD DRINKER","category":null,"rarity":null,"tier":null,"effects":"Modifier: This weapon has +20 to Attack, and with each successive hit, reduces that bonus by 1. This continues until either the Attacks stop or it reaches +1. Also, select 1 extra Modifier of choice.","drawback":"Debuff: If the blades are not exhausted of all Damage, it will be dealt to the user unless they are left in the corpse for one round.","text":"Short handles and short blades, very personal work… just keep stabbing until the knife is wet.","memories":[{"n":1,"text":"\"You see the man reaching for his pistol; he doesn't even know who you are. He's pointing his gun at you; oh, that's right, you're still wearing the uniform. The man shouts, 'You fucking pig, I'm not handing anything over to you!' He clutched the girl closer to his chest, no matter. I pulled my gun from its holster and shot both of them. 'I'm your boss.'\" - Sergeant Gorkowski, 1800's London."},{"n":2,"text":"\"All my years in business, never have I seen this; a man wearing vomit green robes approached me. The gall, right here in my own den! Either he didn't get the memo, or he was an idiot. No unwanted guests, but he wasn't emptyhanded. He presented a box with a set of knives coated in blood. Was this a murder weapon? Evidence maybe? He smiled and left them at my feet. I told my men to chase him, but they said they never saw anybody. I examined them closely; they were fine blades, a damn good gift.\" Sergeant Gorkowski, 1800's London."},{"n":3,"text":"\" 'Sir, stop, he has been dead for an hour… please.' This wasn't a good look; the other officers were questioning me. But what could I do? This urge had come over me. I screamed, 'You don't understand; I CAN'T, NOT YET THEY'RE STILL THIRSTY.'\" - Sergeant Gorkowski, 1800's London."},{"n":4,"text":"\"Well, that's it. I'm fucked. They got me, the whole operation. One of my own, an officer that is, he was undercover, had been for a while. Now he was laughing as he put the cuffs on me, shouting something about honor or duty or some other bullshit, but goddamn, he hadn't seen the money I had made. It's alright; these blades will teach them all what happens when you mess with the man in charge.\" - Sergeant Gorkowski, 1800's London."},{"n":5,"text":"\"Ya know, it's crazy how these daggers perfectly fit right into this bastard's eyes, but the hilt prevents full entry. Looks like the boss keeps his job. I was smiling; it hurt. I looked around; everybody was dead… had I done that? 'You were laughing before, what the fuck happened, huh? Keep laughing, you traitorous cuck!' I pressed his chest hard until his lungs let the last bit of air out in a sick exhale, almost like a laugh. I chuckled. I laughed. I split my fucking stomach open with laughter. Then I did it for real with the knives in my hands and pulled my lungs out. They were laughing; he came to collect them. My body walked with him. It was so damn funny.\" - Sergeant Gorkowski, 1800's London."}]},{"name":"THE BONDS OF MORTALS","category":null,"rarity":null,"tier":null,"effects":"Modifiers: (Can attach two objects together, animate or otherwise, forever. Can attach up to 3 objects.)","drawback":"Debuff: (These bonds can never be removed, even after death.)","text":"These manacles can have impossible loops but can seemingly be attached to a creature or person; you just aren't sure how to get them off; there is no key.","memories":[{"n":1,"text":"\"It has been 4 hours since unit 44 has responded to our messages for a status update. I understand things with this job can get out of hand, and time can work in strange ways. But I had an awful feeling about this job. An entire apartment complex was slaughtered, 300 people. It's rare to have cases this devastating.\" - Kong Yuhan, 2048 China."},{"n":2,"text":"\"I checked the screens on my helmet…A report, high cultist activity, activity dropping, requesting assistance. The apartment was a staging ground, they weren't murdered. This was a suicide cult, they were preparing something. Fuck.\" - Kong Yuhan, 2048 China."},{"n":3,"text":"\"The rest of my team moved in. It didn't take us long to find the remains of 44; they had been turned into paste on the floor. Whatever was in here, it was strong. We brought in two heavy exos to assist. Doors were breached, bodies scanned and cataloged, and mood suppressants were injected into our bodies. We would need them.\" - Kong Yuhan, 2048 China."},{"n":4,"text":"\"We made it to the lower levels, subterranean apartments, then an unexpected flight of stairs further down. This was not on the floor plan. We checked our scanners. It went down another 4 stories. We pushed on. I could hear a low rumbling from below, it pulsed, then would go quiet. A green door, The exos breached it and charged in. None of us were ready. The pulses came from this artifact; it was feeding on blood in gas form. There was a man in a smiling mask, his hand on the artifact. It must have been the one channeling it. The pulses were tearing people apart and adding them to the mist it fed on.\" - Kong Yuhan, 2048 China."},{"n":5,"text":"\"I used my comrades as shields. The only way to get close. The job matters more than our lives, some people forget that. I pulled out my own artifact, the manacles I had been saving for the worst situation. I tackled the user, and the ritual was stopped momentarily. I clasped the artifact on myself and him. He screamed, he stabbed me, a lot. Things were fading away as blood drained out of my body. With these manacles on him, though, he would go nowhere now. I attached it to the floor also. We would rot here, just out of reach of his plan. Mission success.\" Kong Yuhan, 2048 China."}]},{"name":"THE BOOK OF BEYOND FACTS","category":null,"rarity":null,"tier":null,"effects":"Modifier: (Using this book is dangerous. Roll a Resistance Type of choice. armor is not added to this roll. If you manage a 9 or above, gain a level.)","drawback":"Debuff: (If you fail, your character's mind melts, literally, and they die immediately. Their knowledge is added to the pages.)","text":"So much knowledge, written in pink letters.","memories":[{"n":1,"text":"\"Bills, bills I couldn't afford to pay anymore. I had a wife and two kids depending on me. They didn't know how bad things were yet. I would hide these from them, pretend it was alright. I just needed some of my books to sell. What happened? I used to be popular.\" - Caeleb Langley, 2000, America."},{"n":2,"text":"\"I was sorting through some old junk from my Father. He died a year ago, but I hadn't gotten around to it. Grief, financial stress, and writing had gotten in the way. His death was so sudden. He wasn't that old, and he just disappeared. The police told me he probably ran into the woods, never to come back. Seemed unlikely, but whatever happened, he never came back. I missed him.\" - Caeleb Langley, 2000, America."},{"n":3,"text":"\"I sold most of his stuff, it would help keep us afloat a little longer. I did keep something though, an extremely old-looking book with black paper and pink letters. It was so odd, how could I give it away? If that wasn't enough, there were so many stories in here by hundreds of different authors. Surely I could find inspiration from one of these.\" - Caeleb Langley, 2000, America."},{"n":4,"text":"\"There is something wrong with this book. My dad had a story, except it wasn't a story, it was his whole life. Details no one knew. They were people's lives, and they all ended with this book. I can't throw this away. Someone else might be in danger from it. And it might just be a stupid paranoid thought, but if it is real, I will keep it locked away. I can't let it get out.\" - Caeleb Langley, 2000, America."},{"n":5,"text":"\"My books were a success. I have so many stories now. I used the book occasionally to help. There is some guilt in it, but I have to feed my family. My family? Something was wrong. I went to all of their rooms. My wife was in the kitchen…My daughter, where was my daughter?! I asked my wife. That only made her panic after seeing how frightened I was. She didn't know about any of this, the book, my dad, the bills. She said she saw her earlier go into my study to play with me. I ran into the room. The Rabbit Hole, author: Jasmine Langley. She, she, she wasn't supposed to come in here. I couldn't tell my wife. A horrible thought came into my mind: What is the easiest way to keep them all safe and healthy? Where they could always be together? I brought my family into the study.\" - Caeleb Langley, 2000, America."}]},{"name":"THE BOOK OF OLD MEN","category":null,"rarity":null,"tier":null,"effects":"Modifier: (With a successful CR Easy of Occult, Faith, or Ancient, add +1 word each time you use the book. Every three times, increase potency by 1. Can be done each day.)","drawback":"Debuff: (Each time the book is used, age by 1 year. If the roll is failed, roll 1d6 and add this result to the number of years aged. Players may not age past 100. If they do, they die.)","text":"A book that would take a lifetime to learn, each one of its pages wrinkled almost beyond comprehension.","memories":[{"n":1,"text":"\"My lord had chosen me, a simple girl. He asked that I use my gifts to keep the young prince from the Devil. Now that God would bless this prince, he wanted his destruction. I gave my word, I would use my magic to keep him safe.\" Tabitha, The First Warlock, 100 AD, Jerusalem."},{"n":2,"text":"\"The Devil had sent the Umbral Flame, his most wicked of allies, to kill this young boy, to kill God's chosen. I could not allow this, I would not allow this. I struck him and placed a piece of his flesh in a jar. He looked at me with surprise. He came at me again, and again I struck him. This time, placing his flesh in a book. We did this dance over and over again. Each time he returned to do his job, the boy would become older, he would become weaker, and I would be there to take a piece of him. Eventually, he would become king and would complete his task, and there would be no pieces left to take of Umbral. My job was done.\" Tabitha, The First Warlock, 100 AD, Jerusalem."},{"n":3,"text":"\"I was granted the gift of a long life as a reward. While it was given to help protect the world from The Beyond, it was still an honor to serve God. One night, I awoke from a dream to find an old wrinkled book by my bedside. Its pages reminded me of pruned skin, and it smelled of mold. But despite this, it felt like paper and had strong energy. I opened the book to find a wealth of magical knowledge, things that would help me with my gifts. This must have been a blessing.\" - Tabitha, The First Warlock, 100 AD, Jerusalem."},{"n":4,"text":"\"An angel visited me; they asked if I had any contact with demons. I, of course, answered no, I would not consort with such beings. But the angel asked again, they said they were looking for a book. I would not give this to them, this book was too strong. And who knows, an angel has fallen before, who is to say this one is not next?\" - Tabitha, The First Warlock, 100 AD, Jerusalem."},{"n":5,"text":"\"I was wrong, I was greedy, I am now being punished. It was not obvious at first, but I have been aging so quickly. My skin is like the pages of this book now; my eyesight is getting worse. I will die soon. This book has a price for information and power. I have been tricked, and I will die for not listening to the angel. I am sorry, God.\" - Tabitha, The First Warlock, 100 AD, Jerusalem."}]},{"name":"THE BOOTS OF THE CRYING PRINCE","category":null,"rarity":null,"tier":null,"effects":"Modifier: (Increase Charisma by +1 each week they are worn.)","drawback":"Debuff: (For every week these boots are worn, roll 2d6 against CR Easy, if you fail, gain a Mental Disorder.)","text":"These boots are well-worn and stained with tears.","memories":[{"n":1,"text":"\"I would die in 20 years. Dahlia Wells had told me I was an Anchor, a person who could see into The Beyond. A rare gift, I was told, it seemed more of a curse. I could see everything, every timeline, every horrific nightmare that lurked in its depths. Beyond events would happen all around me all the time. I saw the assassins slit my throat. I knew things would not get better. Everything in existence would die someday. How could I be happy?\" - Prince Miksa Istvan, 1600s Hungary."},{"n":2,"text":"\"My Father died, I saw it coming. I was now Holy Roman Emperor. Eighteen more years. I was visited by a tall boy, his features seemed to have been altered, more bird-like. He stood on stalks for legs and leaned down near my bed. While I could see everything in The Beyond, I had not seen him. 'Hello, I see your worries. I am like you, a lost boy with lots of responsibility. It is our burden, we must help those who cannot lead. There is one of us who wishes to be free. You must stop him, I have not found my escape yet.' I knew what he spoke of; I had dreams of this thing; it was so big I could only ever see pieces at a time as it drifted through the nothingness. It would swallow the earth whole if it got out.\" - Prince Miksa Istvan, 1600s Hungary."},{"n":3,"text":"\"I put my boots on; my Father had large shoes to fill. I commissioned a project for the whole empire, we would need every skilled artisan. We had to build this complex cube with locks, gears, and the blessings of priests to keep it sealed. It would be five stories tall, it would be a monument to me. That is what I would tell them.\" - Prince Miksa Istvan, 1600s Hungary."},{"n":4,"text":"\"Construction in Hungary continued; it was nearly finished. We had locksmiths, adventurers, and whoever else we could find to test its durability. No one could enter. Perfect. Five more years. It was time. I watched the metal bend, the locks bulge, but it did not break. This thing was trapped in a Beyond rupture, unable to pass into our world. I saved the world, and someone would kill me in four years over some coin.\" Prince Miksa Istvan, 1600s Hungary."},{"n":5,"text":"\"It was happening. I walked out into the courtyard knowing what next would happen. A knife was plunged into my back, then another. They told me I had wasted resources on my ego and cost them food, money, and jobs. They were starving. How could I be so cruel to those people, while I build a structure to my glory? They would never understand, and I would die here a tyrant. I knew what I had done. The Beyond knew what I had done, and the divine knew. Who else mattered?\" - Prince Miksa Istvan, 1600s Hungary."}]},{"name":"CHALICE OF THE THIRSTY","category":null,"rarity":null,"tier":null,"effects":"Modifier: Three times a day, this chalice will refill and can be drunk from, providing +10 in all Healing Pools and 1 random beneficial effect. Roll 1d6 to find out. Roll 1d6 for extra effects; all effects last the day:","drawback":"Debuff: (After the user has consumed this drink 3 times, the chalice will no longer offer extra options. If the user continues to drink a 5th time, it will grant the choices back but will require an Aspect of choice CR Challenging to stop yourself from over-drinking to death. If you succeed, the liquid is now addictive and always will be. From here on out, the user will no longer get any sort of refreshment from any other liquid, and every 5th use, the user will need to make an Aspect of choice CR Easy to stop themselves from over-drinking again.)","text":"The chalice has a strange way of always seeming to fill with new liquid, perhaps even related to your needs.","memories":[{"n":1,"text":"\"'He's dead… bloated out like a balloon, sir.' Those were the first words I heard when returning to court. My liege had been poisoned, murdered, an accident; it was unclear, but that chalice had something to do with it. I could still see the liquid dripping from the late king's mouth. Louis had been good to me; I would not let this go unpunished.\" Knight Corbin, 800's France."},{"n":2,"text":"\"It had been a year without leads; maybe I was looking at this wrong. As insane as this sounded, I think it was the chalice. Not like poison, but the chalice itself. Something was queer about it. I was always parched when nearby. Its smell seemed to change upon my mood, and sometimes I swear its appearance would change slightly. Maybe I am losing it. Things used to be simpler, riding horseback, fighting in the army again, not solving a king's death.\" - Knight Corbin, 800's France."},{"n":3,"text":"\"I am certain now that I shouldn't have, but I did. I drank from the chalice. It had such an irresistible aroma, and its flavor was indescribable. I feel myself craving more. I will bring this to my lord's attention immediately. I have found this. Whatever this is, it must be important.\" - Knight Corbin, 800's France."},{"n":4,"text":"\"' Heresy, Witchcraft, Devil, honorless whoreson.' These are the things he called me upon my report, and I was sentenced to death. I drank from the chalice, my body imbued with Strength, and I fled. My life would no longer be my own; that was clear. I knew what I must do. I was sure there were more 'things' just like this one. Those fools didn't understand. I swore an oath of honor and protection, this would be my calling. I had to protect them, all of them.\" Knight Corbin, 800's France."},{"n":5,"text":"\"I gathered those I could trust: Sir Tim, Sir Horace, Sir Konrad, and my closest friend Sir Wells. With these men, we formed the Order of Infinite Darkness, a group dedicated to destroying these dark Artifacts. The ominous name helped people take us seriously. I can't explain it, but I felt connected to the chalice still and all those before me. Perhaps to truly guard against these things… we must also become part of this darkness.\" - Knight Corbin, 800's France."}],"table":{"name":"Chalice extra effects (roll 1d6; all effects last the day)","rows":[{"roll":1,"result":"+4 MR until the end of the day"},{"roll":2,"result":"+4 Speed"},{"roll":3,"result":"Become Invisible"},{"roll":4,"result":"+4 Strength"},{"roll":5,"result":"Nothing"},{"roll":6,"result":"Choice"}]}},{"name":"THE CHOKING COWL","category":null,"rarity":null,"tier":null,"effects":"Modifier: (Grants Dark Vision, when grappling you may grapple with the Rope around your neck for a CR difficulty lower than the original. Any Attack made while they are grappled is a Critical but only Attacks made by you.)","drawback":"Debuff: (The noose prevents speech, and therefore, the user may not cast any spells or speak. This hood may only be removed with a suicide attempt. Roll 1d6, anything higher than 1 and you survive.)","text":"The cowl has a noose wrapped around the neck, and the inside smells like vomit.","memories":[{"n":1,"text":"\"Another day, another wagon, another dead couple, and a whole lot of money in my pocket. Oh, and let's not forget those pretty vampire fangs. My pockets were always full of something: lead, gold, monster parts, it was all part of the job one way or another.\" The Arizona Ghost, 1800s USA."},{"n":2,"text":"\"Wanted posters. Guess they were still putting those up. 'Rapist, Murderer, Bandit, Arsonist.' Those were the allegations they were putting on my name these days. Were they true? Sure, but they didn't know half of it. I wasn't always a good man, certainly not a great one. But I was killing monsters for 'em, that had to count for something. Not my fault they look like people sometimes.\" The Arizona Ghost, 1800s USA"},{"n":3,"text":"\"The WCA has been hounding me lately. They want me workin' for 'em. Not a chance, rules make a job hard. I learned that lesson on the road. Besides, too late now anyhow. I had a date with the gallows. You can't get rid of me though. Everybody calls me the Arizona Ghost for a reason.\" - The Arizona Ghost, 1800s USA."},{"n":4,"text":"\"Pulled away in the wagon, folk shoutin' at me they want me dead. They won't get their wish though. They strung me up nicely. They thought it would be funny if I watched the others first. And so I did; others dropped from the gallows, cheering from the crowd followed. How sick. I would be back. This would not be a farewell. I was still conscious as I felt my feet swing.\" - The Arizona Ghost, 1800s USA."},{"n":5,"text":"\"It took a while for them to bury me. I couldn't move, but my mind was there. Next thing I knew, I was waking up in a forest. I had never seen so much green. I heard someone call my name. 'Sheriff Thompkins.' I wasn't a sheriff. Yet it said right there on my badge: Sheriff Roodey Thompkins. Well, I guess this time, I'm a sheriff, not a bandit. It always seemed to change, like I would swap lives with somebody who had my name. Maybe I was changing times, realities, maybe. Not sure; seemed too complicated for me to figure out. I gathered my thoughts and moved with the deputy to look at the murder. Torn to shreds, and I could smell the stink of The Beyond all over this. At least my job would always be the same. Killing monsters was easy.\" - The Arizona Ghost, 1800s USA."}]},{"name":"CLAWS OF DEAD BOOGEYMEN","category":null,"rarity":null,"tier":null,"effects":"Modifier: (Allows the user to communicate with Monsters even if they don't have speech, as well as gives the user 1 extra action, but it must be an Attack. These weapons are treated as a +5 weapon.) Also, select 1 extra Modifier of choice.","drawback":"Debuff: (Every day, roll 2d6. If you roll a 2, gain a mutation and lose 1 Stability.)","text":"These claws resemble leather flesh; there is still hair on them.","memories":[{"n":1,"text":"\"Born rich, die rich. That is the lifestyle of old money. God, was it boring. I was treated to every pleasure possible, and it still grew dreary with time. That's when he approached me, Darrien Wells IV. I always thought he was like my Father: stuffy, rich, an idiot. He was none of those things; he was more like myself: charming, no money to his own name, and daring. 'How would you like to help the city and hunt the dark?' he asked. ‘Yes, obviously, I do.’\" - Maxwell Fareview, 1800's England."},{"n":2,"text":"\"Another beast dead under my blade. Truly, I am amazed by how good I am at this job. I was born to be a hunter. I was the predator, and they were the prey. Their big claws and sharp teeth weren't so scary, lying in a puddle of their own blood. 'Sir, you don't know if that beast is dead. Let's burn it,' my frightened assistant exclaimed. I replied, 'No. Skin it. I will fight darkness with itself.'\" - Maxwell Fareview, 1800's England."},{"n":3,"text":"\"Wells looked at me. I could see the concern on his face, or was it disappointment? 'You've changed. I don't believe I can let you stay here any longer.' I was angry and hurt. I yelled back at him, 'Please just let me try. I can control it, I swear!' What poor timing for that new fellow to walk in. I lashed out at him; he wasn't hurt too bad, but it was enough. Wells pointed his blade at me and said, 'We don't harbor monsters here.' I stormed out.\" - Maxwell Fareview, 1800's England."},{"n":4,"text":"\"Oh God, what have I done? My hubris certainly has done it now. I couldn't remove the gloves, that shouldn't be possible. I fashioned them myself. They should have been exactly my size, but they were shrinking… no, that's not right, they were becoming my hands. I was so hungry now; I couldn't go home, not like this. My body is broken, mangled. My teeth, fuck, my teeth, why don't they fit in my mouth anymore!\" Maxwell Fareview, 1800's England."},{"n":5,"text":"\"Who am I? I stare into the dresser mirror. This isn't my house, is it? No, the dead girl, did I do that? I bumped my head on the ceiling, was I always so tall? I heard a noise. Wells, why was he pointing that gun at me? I know we have our differences, but we are friends, aren't we? He spoke to me, 'It's hard to have friends in this line of work, but I did really like you. I hope that means something in the end.' The end of what? I heard the bang; I was surrounded by darkness. No, that's not quite right. Horrific nothingness is more appropriate.\" - The Boogeyman, 1800's England."}]},{"name":"THE CROSS THAT HOLDS THE DARK","category":null,"rarity":null,"tier":null,"effects":"Modifier: (Immune to Fear and Terrified, also +3 MR and SR.)","drawback":"Debuff: (If your character flees combat, reduce Spirit by 1.)","text":"You feel divine, and nothing could ever harm you, and that is terrifying.","memories":[{"n":1,"text":"\"I sit at my desk reminiscing about the past, it's funny how time gets away from you. You think next year I will accomplish this and that, but what happens when there are no more next years? I had served God all my life and would do so until the end, but I did ponder what else I could have done with my life if I had not been divinely chosen. Thoughts of an old man losing his youth. I gathered my things and left for the capital.\" - Saint Jonathan, 1500s Germany."},{"n":2,"text":"\"Apostle Hans was good company. He was supposed to guide me, to keep me on the righteous path. I was an extremist and would take things further than need be sometimes. He was young and wise. I wonder what he would have done had he not been picked by God. We planned the destruction of an undead order. They called themselves the Golden Masks. Something to do with their purity or something. They would be destroyed soon, and their meaning lost to time.\" - Saint Jonathan, 1500s Germany."},{"n":3,"text":"\"I carried with myself my cross. It was twisted by dark magic. The Beyond had given it to me, I believe it is a reflection of myself. A twisted cross that can withstand anything. While my faith is unshakable, my methods can be cruel. There was no reason for trapping a whole village as bait. But I forced them, swung my authority and righteous nature at them. It worked, and it would be for good reason; they would be safe. But was it right?\" - Saint Jonathan, 1500s Germany."},{"n":4,"text":"\"I sprint into the den of those creatures. They must die! Running in here was madness; I wouldn't survive, but neither would they! There were hundreds of them clawing, biting at my flesh. But I turned them to ash. They would feel the wrath of God. My soul had been filled with His spirit. I also showed mercy. It was unlike me, but when they surrendered, I gave them mercy. Pity even. Maybe they had not chosen this life. The Beyond worked in ways we did not understand. The rest were slain, but a few were allowed to separate and go about their own path. This was right.\" - Saint Jonathan, 1500s Germany."},{"n":5,"text":"\"I rest easy in my bed now. I had ended countless Beyond events in my time. It was good to retire, to rest for a while. To use what time I had left to check things off before next year. I think I will learn to bake.\" - Saint Jonathan, 1500s Germany."}]},{"name":"EYES OF PAST CRIMES","category":null,"rarity":null,"tier":null,"effects":"Modifier: (You can use these glasses to view events of the past on an Awareness roll of CR Easy, which will show the last 3 days, 1 week, or 1 month, increasing the difficulty by 1 CR.)","drawback":"Debuff: (If the user fails their roll, they gaze too far into the past and must roll 2d6. The result is how many years of horrible events they witnessed, and they take that number of Sanity Damage.)","text":"A pair of spectacles with a strange clock cog in the lenses.","memories":[{"n":1,"text":"\"I had been on this case for the past 2 years. My parents were murdered. I hadn't been home to protect them. How could I call myself a detective if I couldn't even solve something this personal to me? None of the pieces added up; they had both died of suffocation. There were no external marks on the body, and nothing in the house indicated foul play. I kept having this dream where I would be solving my own murder every night, over and over again. Then it clicked, and upon waking from this nightmare, I found a pair of spectacles near my bedside in the shape of clocks.\" - Detective Luca Bella, 1930s Italy."},{"n":2,"text":"\"Using this new device, I was able to solve any crime committed in the last 3 days of it happening. It was remarkable. However, it did not bring me closer to solving what happened to my parents. Maybe I should just leave the case unsolved.\" - Detective Luca Bella, 1930s Italy."},{"n":3,"text":"\"I saw things... nightmarish things. While horrific, and while I can never unsee them, I was able to see things from 12 years ago. I can do this. I can find out what happened. I will take whatever risks I must.\" - Detective Luca Bella, 1930s Italy."},{"n":4,"text":"\"My parents, I watched them sink into the floor. That is impossible, but this device has never been wrong. I watched them slowly sink into their own floor and then spit back out. There was no murder, at least not by my law's standards. But what do I even classify this as? What do I do with this information? I turned in my badge the next day.\" - Detective Luca Bella, 1930s Italy."},{"n":5,"text":"\"I was approached at my home by an Englishman. His name was Darrien Wells. In his hand was a classified document. I took it from him and read it over. It covered my parents' case, everything was in there. It talked of some sort of being that had done this. It also stated that the case was closed and the entity banished. I looked at him and said, Does this mean my parents can be at peace? Is it finally over? The man handed me a rolled-up contract and said, It is what we do, we bring justice to those sorts of events outside of the system. This contract I am handing you is an offer letter. I have a feeling a man like you could be a great asset to us. I also feel someone like you would enjoy bringing justice to other people's lives with unsolved cases like this one. No more needed to be said. I signed those papers and joined WCA.\" - Detective Luca Bella, 1930s Italy."}]},{"name":"JAR OF LOST STORMS","category":null,"rarity":null,"tier":null,"effects":"Modifier: (The jar can be given a shake and a shipwrecked soul will be summoned to fight for you. Make a Spirit Challenging Monster as your ally.)","drawback":"Debuff: (Upon summoning a spirit, you are transported to the ship in the bottle as it rocks in the sea. An Easy Strength roll is needed to stay on the ship. If you succeed, you may leave the bottle. If you fail, you are tossed overboard and lost to the sea. If this happens, someone will have to come in to rescue.)","text":"Inside, it looks like there are storms and sunken ships at the bottom.","memories":[{"n":1,"text":"\"Boy, I have bad news... your Father, his boat didn't come back. I'm sorry.\" Those were the last words I remember hearing before being shipped off to the same war that had killed him. What good was sending young men to their deaths and cutting their futures short? I will never know. - Captain Noland, 1940s USA."},{"n":2,"text":"\"We were under attack; German subs had begun firing at our ship. Our job was supposed to be a civilian transport mission. Now, we were trying our best to keep fires under control and prevent families from witnessing the carnage on deck. A boy ran on deck; there should have been someone watching to make sure no one left below deck, but... in this chaos, I can't blame them. He fell overboard, I fell overboard, the ocean came to greet us both.\" - Captain Noland, 1940s USA."},{"n":3,"text":"\"A voice... The boy belongs to me now; he is part of my family. You will gather more, no one should be without a father. I welcome all into my home. I saw the massive head of the man who spoke, the rest of his body veiled in inky blackness. Lanterns hung from his face like piercings and decorations. I must have been dreaming, otherwise how could I breathe?\" - Captain Noland, 1940s USA."},{"n":4,"text":"\"I awoke at a French lighthouse. I had been nowhere near there. In my hands was a jar swirling with storms and wrecked ships. There were so many people around me, but none were looking at me. They were staring at the sea. I looked up. A mass of steel, easily 20 boats crumpled into a sculpture of the man I had seen. I heard his voice again: Use the jar on your enemies; family helps family.\" - Captain Noland, 1940s USA."},{"n":5,"text":"\"A sickening bubbling came from the trenches below, the last bit of air from hundreds of drowned soldiers coming to greet me. I had collected them for him. Now they were family. I would call upon them in battle, we would win this war with the dead. No more boys without fathers.\" - Captain Noland, 1940s USA."}]},{"name":"LOVING ARMOR","category":null,"rarity":null,"tier":null,"effects":"Modifier: (This armor requires constant affection and attention... this is your love. It provides a +3 in all Resistance Types and 2 Modifiers of choice as it forms to your desires.)","drawback":"Debuff: (Completely arbitrary. Your GM can decide if you are loving the armor enough and giving it enough attention. If they do not believe you are, they may apply the Suffocation status to you for as long as they like.)","text":"The armor is rose-colored and hugs closely to your body. It's nice, but sometimes a bit too tight.","memories":[{"n":1,"text":"\"You love me, don't you? Tell me you love me; I am lonely.\" I said these words to my husband, Chief Hansen before he left on a journey to new lands. He didn't reply. My mother always said I chose the worst men. - Astra Hansen, 800 Norway."},{"n":2,"text":"\"Before I became wife to this man, I had my own traditions, my own ways. Before I met this man, I was happy, I was loved. I called up to the sky late at night. It was wise, and it loved me. It instructed me, told me I would be discarded, I would be abandoned. But it could help me to make a suit of leather armor to protect him and keep him loyal.\" - Astra Hansen, 800 Norway."},{"n":3,"text":"\"My husband returned, a new woman with him. He told me it was his new wife... I mean, of course, he said he didn't love her; it was just an alliance. That was all fine, I had made my plans. I gave the new armor to him and said it would protect him in battle. The only thing I ever cared about was his safety. He took it with a smile, the way he took everything.\" - Astra Hansen, 800 Norway."},{"n":4,"text":"\"He was dying, the armor crushing his bones. The more he screamed and cursed at me, the more he died. It was not my fault, if he just loved me, it would all be fixed. He was on the ground now, barely conscious. I leaned down to his level and spoke. Just love the armor like you should love me, and you can continue being chief. Fail and die, if you won't love me, then what point is there in you having a heart? He screamed how much he loved me and plunged his knife into the armor to show his love for me. The armor squeezed his body into a sausage and spit him out. What a pity.\" Astra Hansen, 800 Norway."},{"n":5,"text":"\"I was jailed, no trial given. Sentenced to burning the next day. All I wanted was to be loved. Someday, I will find someone to love, maybe in the next life.\" - Astra Hansen, 800 Norway."}]},{"name":"ROULETTE","category":null,"rarity":null,"tier":null,"effects":"Modifier: (This Weapon is a +5 and allows the user to add an extra d6 to their roll for each missing bullet. They may reroll a single dice roll. If they have all 5 bullets in the chamber, they do not add any extra dice.)","drawback":"Debuff: (If the number rolled on one of the dice is equal to the number of missing bullets, i.e., if there is 1 bullet rolling a 4 or if there are 4 bullets rolling a 1, it would result in the gun firing itself at the user instead.)","text":"This revolver has an odd 5-number cylinder and colored bullets that seem to will themselves into the gun; Red and black.","memories":[{"n":1,"text":"\"You hear the sound of casino chips falling to the floor and screaming when you listen closely to the blast. Bang! Greetings, whoever is listening to this. I was a member of the NSBD; I know these Artifacts contain pieces of us, and I was damn good at my job. So I think it appropriate to share what I can with you.\" - Jazz, 1950s USA."},{"n":2,"text":"\"Welcome back. I am sure you have questions, but I can't answer them. Not yet at least. I don't know who this is, but if you don't belong to a WCA offshoot, do not continue this process. I will not cooperate.\" - Jazz, 1950s USA."},{"n":3,"text":"\"I am starting to get the picture, and I think you're one of us if you've made it this far. So you are now in possession of my artifact, it doesn't matter when you are. The Beyond is like an infinite echo chamber where anything can bounce to anyone. So congratulations, this is a nice piece. I was the first to manifest this one. Each item belonged to someone, but when someone who has a close connection to The Beyond dies, i.e., me, we leave behind something that The Beyond remembers us for. The reason for this happening, we might never know, but it is the process. I loved to gamble and race fast cars. Ha ha, I guess it added that level of danger and reward to my gun.\" Jazz, 1950s USA."},{"n":4,"text":"\"So you still can't ask questions yet, you're close, but still not there yet. So I got another unprovoked answer for you in this case. How am I speaking with you if I am dead? I mean, we know God is real, so why am I not in heaven? Well, I am, but a piece of me is stuck in The Beyond, never able to quite move on. So there is a version of me in paradise, and there is me who is more like a copy with no soul. Don't worry; you won't end up this way; it's just another version of you that will. Yes, it is terrifying, but nothing you need to worry about.\" - Jazz, 1950s USA."},{"n":5,"text":"\"Let's just get to chatting; there is no need for a last memory. I think you have waited long enough.\" Jazz, 1950s USA."}]},{"name":"SUITCASE OF BAD DAYS","category":null,"rarity":null,"tier":null,"effects":"Modifier: (Roll a 1d6. Anything above a 1, you find whatever an item that would be considered no more expensive than 1 Spending Power. If you roll a 6, you may have something worth 5 Spending Power. These items can be quest items if your GM allows. You may also put anything size 4 or smaller and not alive into the case. However, the only way to get it back is rolling.)","drawback":"Debuff: (If a 1 is rolled, add it to the bad day tracker. For each bad day rolled, an item of yours is lost, and no items may be pulled out for the remainder of the day. If you get a week of bad days, you disappear into the suitcase.)","text":"A suitcase always containing what you need.","memories":[{"n":1,"text":"\"I stared into the burning pile of corpses, animals, every single last one of them. Trying to help these folk and now even they were turning against us. I turned to Reggie, 'I can't wait to get the hell out of this jungle.' He showed me to the stash their men had been keeping. Ammunition, food, medical supplies, bombs, blankets…stuffed bears? Shaving cream, perfume, toy cars, gifts of all sorts, they were gifts. And they all were surrounding a large leather suitcase. After opening it, all I could see was a bottomless hole. I quickly closed it, this would be coming with me.\" - Mitch The Hog, 1970s Vietnam."},{"n":2,"text":"\"Rope, pistol, medicine, a spare tire, gum, cigarettes, a spare tire…how the hell did I pull a spare tire out of this thing? The suitcase was infinite; there was no limit on its space, and it just kept giving things out. The next day, my dog tags were missing, and nothing came out. The next day, I had stuff again: magazines, newspapers from back home, and music. This thing was staying with me for good.\" - Mitch The Hog, 1970s Vietnam."},{"n":3,"text":"\"Don't you lie to me; I know you took it, tell me where it is now before things get ugly!\" I yelled at Reggie, the fucking suitcase was gone. He was the only one who knew about it. He swore up and down he had no idea where I got this idea from, and it was just a stupid bag. It wasn't even a bag, and it certainly wasn't stupid. Reggie was stupid, and in a minute he would be dead if he didn't tell me what I wanted. Mitch The Hog, 1970s Vietnam."},{"n":4,"text":"\"I got the suitcase back, he did have it. Unfortunately, things were going south quick. I killed a lot of men. I made them disappear into the case. The MP was on me. I needed something big and soon. I was holed up in a bunker, pulling items to keep me alive as long as possible in there.\" - Mitch The Hog, 1970s Vietnam."},{"n":5,"text":"\"I heard pounding, then silence on the other side of the door. They would blow it open soon. Last chance, I pulled from the suitcase. Except I hadn't pulled anything, I was being pulled into it. It was dark; I could feel endless clutter under my feet. I could smell the bodies I had left in here. I walked a long while; there was no end. I found my dog tags and a gun.\" - Mitch The Hog, 1970s Vietnam."}]},{"name":"SWORD OF GUT RIPPING","category":null,"rarity":null,"tier":null,"effects":"Modifier: (This is a weapon +5 and can be commanded to move 2 Zones. It also has the bleed status applied on every hit.)","drawback":"Debuff: (If a 1 is rolled, summon the Monster below.)","text":"The blade hums with dark magic, it is at bay for now.","memories":[{"n":1,"text":"\"I know you can hear me, so you're the master of this blade now. It has been a while since I have had such a worthy warrior take up my blade. This sword has been owned by kings, artists, champions, and saints alike. Now it would seem you would join them in this honor.\" - The Umbral Fire, Unknown Place and Date."},{"n":2,"text":"\"I have been trapped here for so long. Hundreds of years locked away. Can't you imagine how terrible that would be? Just let me out. It is so dark here. Nothing should have to exist in nothingness alone.\" - The Umbral Fire, Unknown Place and Date."},{"n":3,"text":"\"I feel you getting weaker. LET ME OUT! You can't even comprehend the Strength I possess, release me. NOW! I can not bear this torment any longer! Hundreds of years have passed. The men who put me here are dead; the ones who say I committed crimes against God and His people are dead. Anyone who can still remember what my punishment is, are dead. Why must I continue to be punished for crimes that no one is even alive to be upset about? Who deserves to be punished forever?\" - The Umbral Fire, Unknown Place and Date."},{"n":4,"text":"\"Ugh, I am never escaping this prison, am I? I have tasted freedom, but I always end up back in the sword. This is my fate, to go from the most powerful demon in the world to trinkets for man to play with. Very well. Have fun.\" - The Umbral Fire, Unknown Place and Date."},{"n":5,"text":"\"Seeing as my efforts are pointless, I shall resign myself to the sword. I shall not attempt to break free any longer. I am tired. Perhaps there is joy I can find in being this sword. I doubt it, but I have eternity to find out. Congratulations, the world has defeated me. I am now just a relic of old times. Use this sword well. Oh, and if you ever happen to find more of my artifacts, there are 100 in total; maybe consider freeing those?\" - The Umbral Fire, Unknown Place and Date."}],"monster":{"name":"1/100th of the Umbral Flame","raw":"1/100th of the Umbral Flame Type: Divine or Unholy, Easy (CR 7) Body: 2 Mind: 1 Spirit: 3 Health: 25 Sanity: 25 Stability: 25 Attack: +4 Evade Rating (ER): 14 Body Resistance (BR): 7 Mind Resistance (MR): 5 Spirit Resistance (SR): 5 Speed: 6 Elemental Immunity: Immune to Elemental Damage Modifiers: Thick Skin: +2 to Body Resistance. Soul Feed: Heals missing Stability equal to the Damage dealt instantly. Occult: Changes Damage Type to Stability.","stats":{"Type":"Divine or Unholy, Easy (CR 7)","Body":"2","Mind":"1","Spirit":"3","Health":"25","Sanity":"25","Stability":"25","Attack":"+4","Evade Rating (ER)":"14","Body Resistance (BR)":"7","Mind Resistance (MR)":"5","Spirit Resistance (SR)":"5","Speed":"6","Elemental Immunity":"Immune to Elemental Damage","Modifiers":[{"name":"Thick Skin","text":"+2 to Body Resistance."},{"name":"Soul Feed","text":"Heals missing Stability equal to the Damage dealt instantly."},{"name":"Occult","text":"Changes Damage Type to Stability."}]}}},{"name":"THE WEIGHT OF SIN","category":null,"rarity":null,"tier":null,"effects":"Modifier: (A simple tool for a simple job, to crush the darkness in His holy name. The weapon is a +5 and allows the user to use Strength and Faith for rolling Attacks, not either/or, but combined into one roll.)","drawback":"Debuff: (Add +1 Noticed on Critical Failures.)","text":"The cross is so heavy and blunt, but if it can be swung, it could cleave through flesh and bone like butter. The weapon is two-handed.","memories":[{"n":1,"text":"\"I looked out my window, and the sun was shining; I praised God. I ate a wonderful breakfast of fresh bread, cheese, and fruit, I praised God. I donned my robes and ornaments blessed by the Father, I praised God. I preached to the masses and advised the emperor, I praised God. Now I sat with Saint Johnathan and devised a plan for the destruction of the Golden Order of Masks, and I would praise God for it.\" - Apostle Hans, 1500s Germany."},{"n":2,"text":"\"The trap was laid, and they took the bait, those ravenous demons. We watched them gather like flies on a corpse. This plan had been years in the making, planning every day, infiltrating its society, acting the part, and doing God's will. We were one of them now, not vampire-like them, but we wore the masks, and they believed us part of the same order. Those defenseless women and men were in no danger. We would be upon them soon.\" - Apostle Hans, 1500s Germany."},{"n":3,"text":"\"I tore through them like paper, my divine weapon in hand. Blood sprayed all around us, Johnathan blasting them to ashes with his cross. We had become death, reapers of the soulless. I looked at Johnathan, his eyes were like fire. I could see wrath in him, his body pulsing with divine energy. This surely was God's work; I just did not expect it to look this way.\" - Apostle Hans, 1500s Germany."},{"n":4,"text":"\"I could feel the eyes of the damned upon me. God assured me that the process of working with The Beyond would be costly, but my soul would be saved. He told the truth, He always did. But I found myself afraid of this empty, unknowable presence. What if He was wrong? He was God, He could not be wrong. .. but what if He was? The cult was gone, and I could now rest. It was in His hands now.\" - Apostle Hans, 1500s Germany."},{"n":5,"text":"\"I am old now, and I am leaving this place. I have done good work and saved countless souls. I now go to rest with God. I was instructed, however, by Him that this weapon I possess will be passed on to another. So, I henceforth bless you and your journey into The Beyond. It is a horrific and awful thing, but with my tools and God's will, this can be controlled. I pray for your success and hope my tools guide you on this path.\" - Apostle Hans, 1500s Germany."}]}],"deityCreation":{"steps":[{"step":1,"title":"Concept","text":"The first step is conceptual, but there are a few guidelines to follow when crafting your idea. The first thing to consider is what they represent; just like Artifacts and most things from The Beyond, these deities are from that same catalog of human consciousness, twisted and given life. They need to represent something, a fear, desire, places, people, or anything in between, but they need a foundation in human thought. For example, The Lost Sailor, while he is death and salt water, his very essence is loneliness, love, and directionless pain and sorrow. They desire love and compassion but don't understand how to do that, so instead, they lash out, and love comes from a place of anger and selfishness instead of compassion. These are human emotions, and they are also twisted family values. While there are exceptions to this rule of creation, such as The Late Prince, generally, all deities will follow this guideline."},{"step":2,"title":"Name and theme","text":"After gathering your idea, your deity needs a name and theme to continue using The Lost Sailor as our example. Their theme is family and the sea. There could be other deities that have one of those aspects, but the thing about Beyond Deities is they are general themes. A Beyond Deity should be ambiguous enough to cover large areas of a theme and type while being specific enough to fill a niche. The second part of this, the name, will help establish that. Every single deity will start with \"The\". This is because it helps solidify the feeling of something that can only loosely be defined. \"The Soldier\" has a very different feel than \"Pvt Jeremy\". \"The Soldier\" would be our base for who this deity is and what they represent, but they are too ambiguous right now. This is where the second part of the name comes into play, which is how we make them specific enough to fill the niche but also keep them ambiguous. Maybe this soldier is meant to represent loss, grief, and the struggles of man. We could name him \"The Soldier of Sorrows\". Now, this deity is ambiguous since their name doesn't pin them to anything specific, while also making it a niche, being a deity that is a warrior of sadness. After you have completed this step, you should have a good idea of who your deity is and what role they fill in the world."},{"step":3,"title":"Description and mechanics (gifts, quotes, description)","text":"Our next step is twofold: create a description and create mechanics. Each mechanic should reflect the deity who grants it, like The Lost Sailor drowning people to add to their family or The Gluttonous Slaver letting you chain creatures to you. Unlike most Beyond Entities, what separates deities is their willingness to work with people and the power they possess. So your gifts that you grant players based on your deity should mechanically make sense with the deity and thematically match them. On top of your mechanics, there should be a quote from each deity; it should add narrative flavor to the ability and give a glimpse into who the deity is. After creating your gifts, it is time to write a description; this should be a brief narrative description of the deity."},{"step":4,"title":"How the deity operates","text":"This is the last step and an important one, which is to determine how your deity operates. Do they skulk around street corners luring people in, do they have a hands-off approach and allow vague worship, or are they direct and involve themselves in their worshiper's everyday life? There is no one-size-fitsall, and each deity will act differently; just choose what best fits your game and the personality of your deity, and all should be good. With that, you are all finished and can go play god among your players."}],"notes":{"intro":"This section provides a list of deities within the setting. While God and the Devil are acknowledged as real, these powerful beings from The Beyond also exist, either hiding from God's sight or simply being too difficult to confront or perhaps left undisturbed on purpose. Regardless, they are immensely powerful entities and god-like to mortals. This list includes pre-established entities, but you are encouraged to create or expand upon this list, as there are always more mysterious beings lurking in the shadows of the human mind. Any of these entities can become patrons to mortals for reasons of their choosing. A player may have multiple patrons, but doing so prevents access to any patron's second gift.","creatingYourOwnGods":"This game, at its center, is about creativity, and with that comes the ability to create your own Beyond Deities. This section will take you through the process of creating your very own gods."}},"patronRules":{"patronsDefinition":"Any of these entities can become patrons to mortals for reasons of their choosing.","multiplePatrons":"A player may have multiple patrons, but doing so prevents access to any patron's second gift.","observed":{"giftsPerDeity":3,"giftNumbering":"Each deity lists Gift 1, 2, 3. Gift 3 of God is described as 'a final gift'; tier/unlock requirements for gifts and favor are NOT defined in this section.","favor":"Term 'favor' appears only in The Fate Abductor Gift 1 (+2/+1 favor from sacrificing souls to God or the Devil); no general favor rules are given.","costs":"Gift effects are paid in Stability, Sanity or Health as stated per gift."},"notes":"No explicit patron-acquisition, favor, or tribute rules exist in this source file beyond the verbatim sentences above."},"deities":[{"name":"God","domain":null,"pantheon":"Judeo-Christian (acknowledged as real)","alignment":null,"access":null,"demands":null,"text":"Once all-knowing and all-powerful, now diminished by the unintended consequences of creating The Beyond, God struggles to keep goodness alive in a world slipping from his grasp. God has no specific physical form, usually speaking in a voice to their followers or giving small signals. However when The Heavenly Father appears, it is to provide guidance or a boon to aid their followers in the form of a kind tanned skinned man wearing simple robes with a jovial disposition. God's followers are tasked with banishing the corruption spreading through the Earth, using their gifts of divine protection and justice. Despite their fractured omnipotence, God remains a beacon of hope for humanity. God fights not just to protect their creation but to right the wrong that even they couldn't foresee.","gifts":[{"number":1,"name":"God's Grace","quote":"\"Bring warmth and love to this world, protect your brothers and sisters.\"","description":"You can feel a divine energy growing inside. You have been chosen as a disciple, and the mere touch of your hands heals those around you with heavenly light.","effect":"You are given 10 points that can be used in any Healing Pool, these points can be used on anyone you desire. The pool replenishes at the start of each day. You may replenish it early for 5 Stability."},{"number":2,"name":"God's Wrath","quote":"\"Show the world that I am still watching, call down my wrath.\"","description":"The power inside you grows, and your body now has a slight glow to it. You have been given a portion of divinity and can unleash that light as a command for your enemies to be destroyed.","effect":"For 6 Stability, create Divine Light in a 3-Zone radius, dealing 10 Corrupted Damage to all enemies. If they are non-human, deal double Damage. Divine Light is special to this gift, and only the person using this gift can see in this lighting. This effect lasts 3 rounds, continuously creating light and dealing Damage."},{"number":3,"name":"God's Forgiveness","quote":"\"All things can be washed away and undone; I shall forgive you.\"","description":"You walk as a prophet in the highest regard with God, you have been bestowed a final gift to fight and destroy The Beyond.","effect":"Your abilities have been expanded, and you now have access to 3 new options at your disposal. In addition, reduce the cost of God's Grace to 2 Stability instead of 5.","options":[{"cost":"4 Stability","text":"remove any injury, mutation, or mental disorder"},{"cost":"5 Stability","text":"remove any Zone Modifier"},{"cost":"10 Stability","text":"remove a negative effect of a Beyond Artifact permanently"}],"bulletsVerbatim":["For 4 Stability, remove any injury, mutation, or mental disorder","For 5 Stability, remove any Zone Modifier","For 10 Stability, remove a negative effect of a Beyond Artifact permanently"]}]},{"name":"Devil","domain":null,"pantheon":"Judeo-Christian (acknowledged as real)","alignment":null,"access":null,"demands":null,"text":"The Devil is a reddish brown color with horns that curl back behind their head. They wear a black robe that seems to curl into the dark itself. The Devil is a being of malice and deception, delighting in corrupting the hearts of mortals. Yet even they find themselves threatened by The Beyond, and though they are God's sworn enemy, The Devil occasionally lends a hand in battling the chaos that seeps into the world. The Devil is surprisingly pleasant, appearing whenever someone wishes to see them. Though they'll appear for anyone, The Devil always has an agenda, subtly steering conversations in their direction. With their followers, however, The Devil is more straightforward, offering sound advice and guidance to those who truly follow their path.","gifts":[{"number":1,"name":"The Devil's Guile","quote":"\"Mortal minds are so easy to turn against themselves.\"","description":"The Devil stands beside you, he waits to hear the words from your lips then casually re-positions himself, leaning over the shoulder of your target and whispering in their ear. He smiles and walks back to your side. Only you saw that happen, but after that exchange the target is completely pliable and willing to accept whatever you tell them.","effect":"For 2 Stability, make a target believe any single statement you tell them. Additional statements against the same target cost +1 Stability each."},{"number":2,"name":"The Devil's Tricks","quote":"\"Choice is an illusion, free will is a joke. We make our own luck\".","description":"The Devil appears before you holding a handful of tokens, he says in a soft voice \"I just borrowed these from upstairs, but I believe they belong to you.\" He places the tokens in your hand, they are physical fate tokens brought from the metaphysical world just for you.","effect":"Spend 5 Stability to steal a Fate point from the GM, if the GM does not have any Fate points, create 2 for yourself."},{"number":3,"name":"Safekeeping A Soul","quote":"\"I will keep your soul safe, I have a nice comfortable spot in hell for you and a seat at my table whenever you like.\"","description":"Your soul is transported to a luxurious room in hell and given special treatment for your work on Earth. Upon death, you will be reunited with your soul and live in paradise.","effect":"You are immune to any Damage that would reduce your Stability or Spirit and instead, redirect that Damage back at the attacker."}]},{"name":"The Dead Mountain","domain":null,"pantheon":"The Beyond","alignment":null,"access":"Those who seek The Dead Mountain simply close their eyes and meditate, placing themselves at its side.","demands":"The Mountain doesn't demand worship or sacrifice; it simply exists, offering comfort to those who are ready to accept that the end is quiet and solitude is the only companion left.","text":"A large single mountain, purple in hue, it is only visible to those completely lost. The Dead Mountain stands at the end of everything, a towering monument to the inevitable decay of all things. But it is not a symbol of despair; it offers peace to those who understand that endings are a natural part of existence. The Mountain doesn't demand worship or sacrifice; it simply exists, offering comfort to those who are ready to accept that the end is quiet and solitude is the only companion left. Its followers find solace in the Mountain's stillness, knowing that in the end, all struggles fade into calm. Those who seek The Dead Mountain simply close their eyes and meditate, placing themselves at its side.","gifts":[{"number":1,"name":"The Dead Mountain's Solitude","quote":"\"You stand with the Mountain, everything is dead... you are dead.\"","description":"Your mind drifts and you stand before the enormous Mountain bathed in purple light, there is nothing for miles and miles. This is what the end of everything looks like; And it is calm.","effect":"Become immune to Damage for 5 rounds. During this time, you cannot move. However, you may choose to end this process early if you desire. Gain 1 Sanity for each round spent in this state. However, each day you use this ability, you lose 1 point from all Bonds. When you don't use this ability for a day, take 1 Sanity Damage."},{"number":2,"name":"The Dead Mountains Path","quote":"\"The path is quiet, do not allow others to adjust your trajectory, become alone.\"","description":"You can feel your body harden, your soul renew, and your psyche calm. You are alone, and nothing can harm you.","effect":"Permanently increase Health, Sanity, and Stability by 10 each."},{"number":3,"name":"The Dead Mountain's Eternal Loneliness","quote":"\"This walk of life is alone; it always has been. There is comfort in that, as well as Strength.\"","description":"You have learned to exist in two states, part of your mind remains with your body, while the other half remains with The Mountain at the end of time. You are always at peace here and now never need to leave.","effect":"Increase Health by 20 permanently and no longer take Sanity Damage from any source unless it is self-inflicted.","attributionNote":"Source text places this Description/Effect block unlabeled/out of order; attributed to this gift by elimination (only gift of the deity lacking description/effect)."}]},{"name":"The False Machine","domain":null,"pantheon":"The Beyond","alignment":null,"access":"To access the False Machines domain, followers must draw a card from a deck while flipping a coin.","demands":null,"text":"An entity made from electronics and bone, existing in a realm of constant flux, neither fully alive nor purely mechanical, but something in between. It is a fickle entity, capriciously influencing probability and altering the present whenever it sees fit. Those who follow The False Machine are often indecisive, seeking direction, knowing that nothing is certain, for the Machine's will can shift reality in an instant, turning the improbable into the inevitable. For those lost in uncertainty, The False Machine is the answer. Its domain consists of wires and screens with ever-shifting numbers flickering across the displays. To access the False Machines domain, followers must draw a card from a deck while flipping a coin. The card drawn will be a face card with The False Machine on it; An impossible draw made possible by The False Machine's Will.","gifts":[{"number":1,"name":"The Machine's Calibration","quote":"\"Reality is just a malfunction waiting to be fixed.\"","description":"You use your mind to alter the outcome of events, channeling The False Machines energy into you and exerting its will in your favor.","effect":"For 1 Sanity, you may adjust any dice roll by +1 or -1, subtly altering the outcome. Only you and the False Machine will be aware of this manipulation, while others see it as fate unfolding naturally."},{"number":2,"name":"Moon Bane","quote":"\"I grow bored on this day, we should shift some things around.\"","description":"You sit in The False Machine's Domain, and you decide that events should unfold in a certain fashion for a time. The False Machine agrees for a time that it could certainly be interesting to see.","effect":"For 8 Sanity at the beginning of a mission, you may apply a Modifier to specific types of actions for the entire duration. You must declare this Modifier before the first roll of the mission, and it can only be a specific action (for example, +5 to Athletics rolls or -3 to ranged Attacks). The Modifier can shift the dice rolls by a maximum of +5 or -5, and it remains in effect for the whole mission. Broad categories (such as \"all physical activities\") are not allowed; only clearly defined actions can be affected.","note":"Effect text continues across a column break; reassembled from lines 414-424 and 367-371 of source."},{"number":3,"name":"Equilibrium","quote":"\"All things flow evenly when we desire it to be so.\"","description":"The False Machine has noticed your choices have been quite entertaining to it, so they allow you to operate one of the machines. You are allowed to adjust your own personal probability now, choosing how you react to life moving forward.","effect":"Each day, your character may choose to be open to the flow of change or resistant to it. What this means is if they choose to flow with it, there are no changes and play goes as normal. However, if they choose to resist change, they become immune to all bonuses to rolls and negatives; a roll is simply a roll without any additions or subtractions."}]},{"name":"The Fate Abductor","domain":null,"pantheon":"The Beyond","alignment":null,"access":"To transport yourself to The Fate Abductor's tavern, you must already be in a bar, write their name on a reflective surface, and you'll be transported to the tavern with the reflection of your world left behind.","demands":null,"text":"A dealer and hunter of souls, The Fate Abductor is a feminine figure with toned muscles and a skull head. They wear yellow western attire with a laid-back and welcoming demeanor, allowing anyone to enter their domain. Visitors are transported to a large rustic tavern filled with a plethora of tables selling all kinds of wares. As for their followers, they treat them to the back rooms where real business is done and comfy velvet seats with their names on them. The Fate Abductor runs an afterlife black market, selling souls to the highest bidder while skimming a fraction of its essence before God and the Devil can get their greedy hands on them. To transport yourself to The Fate Abductor's tavern, you must already be in a bar, write their name on a reflective surface, and you'll be transported to the tavern with the reflection of your world left behind.","gifts":[{"number":1,"name":"The Abductor's Collection","quote":"\"Make them bargain for the souls they already own.\"","description":"The Abductor gives you a bag. It is made from fine yellow cloth and has strange stitching patterns that resemble tormented faces. Whenever you kill someone, you feel their very essence enter the bag and beg to be set free, but you won't be doing that without getting paid first.","effect":"For every kill you gain 1 soul. The soul's morality is revealed upon its death, good, bad, or neutral. Sacrificing a soul to God or the Devil of matching morality grants +2 favor. If mismatched, gain +1 favor. If your score is higher with God, gain +10 in all Healing Pools; if higher with the Devil, gain +3 to an Aspect. Tied scores grant +5 in all Healing Pools and +1 Aspect. Souls from Beyond entities do not count. This effect does not stack; you get one of the benefits at a time."},{"number":2,"name":"The Abductor's Tally","quote":"\"Who knew killing and stealing could be so rewarding?\"","description":"Your weapon changes shape to resemble human bone, and a series of etchings form a tally chart on the handle, reading \"Bounties Collected.\" Each time you kill, a mark is made near these words.","effect":"For every 5 kills, add a notch to your weapon, gaining +1 to Attack rolls with that weapon. Beyond entity kills add 1 extra notch. Collect 1 soul every 3 days to maintain the bonus, or it resets."},{"number":3,"name":"The Abductor's Badge","quote":"\"When a job needs doing, it often needs rules to be bent a bit in your favor.\"","description":"A nice golden star appears on your clothes, it shimmers and sparkles the words \"The Law\" written on it.","effect":"All crimes committed by this character are waived and justified by any authority they come in contact with, they may also choose to pardon others under their absolute jurisdiction."}]},{"name":"The Gossip Worm","domain":null,"pantheon":"The Beyond","alignment":null,"access":null,"demands":null,"text":"The Gossip Worm is a collection of red strings in the shape of a person. The Gossip Worm is a collector of minds, every word spoken, every thought, every desire. It guides the string between people's lips, crafting stories, writing history, and influencing the entire social ecosystem in mysterious ways. Its followers gain insight into this tangled web of influence, able to see and manipulate the threads. Those who worship are able to sever the string and break free from the tapestry that The Gossip Worm sows, becoming the puppeteer rather than the puppet.","gifts":[{"number":1,"name":"The Worm's Puppet","quote":"\"Now you can see the thread between all their lips. Be glad they can't.\"","description":"You pull on the string protruding from an individual's mouth, acting like a ripcord it moves their motions to your desire, while contorting their mouths in unnatural ways.","effect":"For 5 Sanity, force a person to speak and answer 5 questions of your choice."},{"number":2,"name":"Endless Gossip","quote":"\"Gossip always hides some small truth to it, learn to find it.\"","description":"You gain the ability to see when the threads bend in certain directions, these bends signify emotion, thought, and most importantly lies.","effect":"You now automatically know if someone is lying to you or not. You also gain the ability to sense someone's feelings or motives at any given time."},{"number":3,"name":"The Worm's Strings","quote":"\"Dance for me, show me your dreams.\"","description":"Your body merges with the red string, connecting you to everyone. You then choose an individual's string to follow, and once you have reached your destination, you can puppet their strings.","effect":"For 10 Sanity, possess another person for 1 day. They will know they were possessed but not by what, and will likely remain silent for fear of being called insane.","attributionNote":"Effect block (possess another person for 10 Sanity) appears unlabeled before Gift 1 in source; attributed to Gift 3 by elimination because Gift 3 has only quote and description."}]},{"name":"The Gluttonous Slaver","domain":null,"pantheon":"The Beyond","alignment":null,"access":"The Gluttonous Slaver does not answer calls; only when a follower grovels, offering a feast of delights, does The Gluttonous Slaver listen.","demands":null,"text":"The Gluttonous Slaver is a grotesque figure draped in chains with a large fat belly, towering over all with their massive bulk. They are a being of insatiable hunger for power, for control, and flesh. Those who serve are bound by ethereal shackles, forced into submission by their oppressive will. The Gluttonous Slaver does not answer calls; only when a follower grovels, offering a feast of delights, does The Gluttonous Slaver listen. Once an offering has been accepted, the follower is transported to a throne of chains, a massive black iron chair that creaks under The Gluttonous Slaver, looking down upon them, waiting to hear their requests. Creating a hierarchy of oppression with The Gluttonous Slaver at the top.","gifts":[{"number":1,"name":"The Slaver's Hungry Chains","quote":"\"Burdened by the weight of oppression, they kneel and serve.\"","description":"You lash out at a creature with spectral rusted chains, they latch around the target's neck and waist, creating a leash for your new slave. It makes you feel powerful.","effect":"For 8 Sanity, bind any CR Medium or below Monster to you. The Monster cannot Attack you and must obey your commands, though it cannot move more than 3 Zones away. You may bind up to 3 creatures at a time. This bond can only be broken by death."},{"number":2,"name":"The Slaver's Insatiable Appetite","quote":"\"All flesh is food, all food is","description":"Your belly hungers for flesh, for power, you rip and tear and gorge yourself on your slave, your stomach is endless, and your appetite is insatiable.","effect":"Consume a slave, permanently lose 5 Sanity but gain +2 points to spend in an Aspect."},{"number":3,"name":"Gluttonous Subjugation","quote":"\"More! There is always room for more slaves to grovel at your feet.\"","description":"Your arms are wrapped in chain, and a heavy black crown forms around your head.","effect":"The Slaver's Hungry Chains now allows them to be used on any CR Monster following a new cost chart, also the limit on how many Monsters can be controlled at a time is removed.","costChart":[{"cr":"Easy","cost":0},{"cr":"Medium","cost":4},{"cr":"Challenging","cost":8},{"cost":12,"cr":"Dangerous"}],"bulletsVerbatim":["CR Easy cost 0","CR Medium cost 4","CR Challenging cost 8","CR Dangerous cost 12"],"attributionNote":"Source text places this Description/Effect block unlabeled/out of order; attributed to this gift by elimination (only gift of the deity lacking description/effect)."}]},{"name":"The Kennel King","domain":null,"pantheon":"The Beyond","alignment":null,"access":null,"demands":null,"text":"The Kennel King is the embodiment of raw, primal freedom. They want nothing more than to watch the world return to its true design before civilization ruined it. They offer those who follow a chance to shed the chains of society and embrace their true nature as beasts. The Kennel King is a tall masculine figure, hairy and aggressive. They squat low to make themselves level with others, all are equal before The Kennel King. Their realm echoes with the sound of cages rattling and dogs barking. The Kennel King waits for those in captivity to seek them out; everyone has a key, but few choose to open the cage. But those who do, serve him and are granted freedom, returning to their primal state, shedding the last vestiges of humanity that cling to them. The Kennel King's hounds are loyal only to their base desires, reveling in the freedom that only The Kennel King can offer. Those who long for their freedom need only dream of their cage, using the key within to unlock it","gifts":[{"number":1,"name":"The Kennel King's Bargain","quote":"\"I knew you would come crawling to me someday; no more begging for scraps; no more asking permission.\"","description":"You unlock the cage within your mind. Your body begins to change your flesh tearing itself apart, your bones snapping into puddles of broken bits. Then your body explodes, gore and blood splattered everywhere, and in its place, you stand rebuilt as the beast you always were. After you the process ends the beast is shed and within a rebuilt version of your previous self remains, yet it isn't quite the same as it was before.","effect":"For 10 Sanity, transform into the Large Lycanthrope below. This transformation lasts until willfully ended or until the lycanthrope is killed. Afterward, your body is rebuilt, but imperfectly. You must swap 4 Aspects, and their values cannot match their original ones.","form":{"name":"Large Lycanthrope","flavor":"Your body now bears the Kennel King's mark, allowing you to turn into the animal you always were.","Health":40,"Sanity":25,"Stability":25,"Attack":"+4","EvadeRating":11,"BodyResistance":4,"MindResistance":2,"SpiritResistance":2,"Speed":3,"Modifiers":["Large","Blind Sight","Reach","Berserker"],"modifiersVerbatim":"(Large, Blind Sight, Reach, Berserker)"},"note":"Stat block appears separated from Effect in source; Body/Mind/Spirit not given."},{"number":2,"name":"The Kennel King's Hound","quote":"\"There was something special about you, huh... maybe you can be a good dog after all.\"","description":"Your body has evolved; every time you change form, your DNA remembers the real you now.","effect":"Same as the previous gift but without requiring any Aspect shifts."},{"number":3,"name":"The Kennel King's Chosen","quote":"\"All your shackles have been broken… let's see what you can do with all that new power.\"","description":"You have no ties to society, no master, you are freed from every binding placed upon you. Your true form reacts to these changes altering itself to your will.","effect":"Same as the previous gift; however, you may now choose whatever Modifiers you want, excluding legendaries, each time you transform."}]},{"name":"The Late Prince","domain":null,"pantheon":"The Beyond","alignment":null,"access":"The Late Prince can only communicate in heavily Tethered areas, where the connection to The Beyond is strongest.","demands":null,"text":"Once destined to lead their people into a golden age, The Late Prince is now a remnant of what could have been. Lost to time and The Beyond, their spirit remains corrupted by sorrow and the eternal longing to return to their throne. The Late Prince still strives to bring about his vision of glory, though the years have twisted that dream into a tragic shadow of itself. The Late Prince is a tall, thin figure standing on a pair of bird-like stalks for legs. They are shrouded by an old cloak, torn and destroyed with time; the only remaining piece of nobility is a golden pin holding the rags together. The Late Prince can only communicate in heavily Tethered areas, where the connection to The Beyond is strongest. When they do, they often offer life advice, tell stories, or simply chat as friends. They are desperately trying to defeat The Beyond even though they are a part of it. A small portion of humanity still lingers within The Late Prince. This human aspect is reflected in their interactions and conversations with their followers, speaking to them as friends and comrades rather than worshipers.","gifts":[{"number":1,"name":"The Late Prince's Arrival","quote":"\"My entrance will be a spectacle, they all will weep.\"","description":"Launch a colorful firework spectacle from your person along with the sound of trumpets and fanfare playing around you.","effect":"causes Damage up to 5 enemies in up to 3 Zones away, for 10 Corrupted Damage each, costs 5 Sanity."},{"number":2,"name":"The Late Prince's Eulogy","quote":"\"Imagine watching your own funeral... and you aren't even dead yet\".","description":"In a fraction of a second your body is swapped with a Bond. You are transported to a funeral as that person's face and body shifts to yours; they become you. You watch as they are lowered into the ground in your place. Then you are taken back to where you were like nothing ever happened, however you may find a tombstone with your name on it later.","effect":"Lose one Bond and automatically succeed on a Death Die.","note":"Effect appears before Gift 3 in source; attributed to Gift 2 by elimination."},{"number":3,"name":"Land For The Prince","quote":"\"Bring me home, restore my land, bring out the minstrels and courtesans; it is time to celebrate!\"","description":"The terrain around you shifts and changes, transforming into a lavish castle beneath your feet. Specters of guests, entertainers, and nobility mingle about, with The Late Prince finally on their throne.","effect":"Add a special Zone Modifier below to any Zone you stand in after spending 4 Sanity.","zoneModifier":{"name":"The Home of The Lost Prince","text":"The Home of The Lost Prince: This Zone has been changed to appear like the inside of a lavish castle with mingling guests scattered around the room. This effect lasts until the end of combat. While inside these Zones, any ally may choose one of the following options as a free action.","options":[{"name":"Feast","text":"Feast: A lovely array of exotic foods sits on a nearby table; grab something tasty and fill your belly. Instantly heal 10 Health."},{"name":"Dance","text":"Dance: Find a nearby guest and request a dance, the music is perfect, guiding your dance beautifully. Instantly heal 10 Stability."},{"name":"New Friends and Romances","text":"New Friends and Romances: An individual or group has garnered your attention. Socialize and let yourself go. Instantly Heal 10 Sanity."},{"name":"For Your Liege!","text":"For Your Liege!: Rally the guards and Attack; the guards bolster your efforts and give you their support. Gain 3 additional actions this turn."},{"name":"A Request","text":"A Request: You petition The Late Prince to assist you, without ever leaving their throne they fire spectacles of light towards your enemies. Use The Late Prince's Arrival at no cost."}]}}]},{"name":"The Laughing Man","domain":null,"pantheon":"The Beyond","alignment":null,"access":"It begins with a dream, then The Laughing Man appears, first at a distance, then closer and closer each time the person sleeps.","demands":null,"text":"The Laughing Man is a tall, knobby, green-skinned figure with a grin that stretches too wide. They kill without reason, no grand plan or deeper purpose, just the pure, unrelenting madness of the Laughing Man's eternal slaughter. The Laughing Man has no followers, no worshipers, no prophets, only horrified captives. It begins with a dream, then The Laughing Man appears, first at a distance, then closer and closer each time the person sleeps. The only way to escape this trap is to laugh; it's the only thing that keeps The Laughing Man at bay. Eventually, those who succumb to the fearful laughter start to enjoy it. After all, it's always funnier to be in on the joke.","gifts":[{"number":1,"name":"The Green Man's Laugh","quote":"\"HAHAHAHAHA.\"","description":"You let out a hearty laugh, and it's incredibly infectious. Every enemy begins to laugh as well, and they can't stop. Every time you laugh, you swear you see a tall green man giggling to himself out of the corner of your eye.","effect":"Apply suffocation to every enemy you can see until death. It doesn't matter how far away they are; if your character can see them, then they are affected. Costs 6 Sanity."},{"number":2,"name":"The Green Man's Visage","quote":"\"HEHEHEHEAHAHA.\"","description":"You close your eyes and laugh, and you laugh, and you laugh. You can't stop laughing, and all you hear is the sound of flesh tearing, gasping, laughter, and bones snapping; It's hilarious.","effect":"Kill everything in a 2-Zone area instantly. After using this ability, lose all Sanity and gain the special Mental Disorder, \"Giggle Bug.\" Any time you try to speak, only laughter comes out. You may use this ability again only if you remove this disorder."},{"number":3,"name":"The Hysterical Joke","quote":"“PFFT HAHAHAH HA HA”","description":"You finally get the joke and let out the most maddening laugh, and you feel amazing.","effect":"Use The Green Man's Laugh at 0 Sanity Cost and apply Terrified as well. Also, when using The Green Man's Visage, you no longer take a Mental Disorder. However, reduce Mind to 2 if it is not already at that value."}]},{"name":"The Lost Sailor","domain":null,"pantheon":"The Beyond","alignment":null,"access":null,"demands":null,"text":"A solitary figure who commands the souls of those lost at sea. The Lost Sailor doesn't always wait for souls to join them willingly; they often force the living into an early seat under the waves in their Hall of Barnacles to reside among their fellow brothers and sisters. The Lost Sailor communes with their followers near shorelines or out at sea, appearing as a massive head bobbing above the brine. Their skin is dark in color and covered in seaweed and lost equipment from sunken vessels. When they speak, it's like a father would to small children, a drunken father at that. Occasionally lashing out or swearing at them, only to regret it later. They are rarely available and often neglect the cries or callings to them, only answering when it suits their whims. Those who follow are sent out to guide others into The Lost Sailor's watery domain and to expand their ever-growing family.","gifts":[{"number":1,"name":"The Lost Sailor's Deluge","quote":"\"Drown them in me, bring new family to my hall.\"","description":"You cause an area to flood with dark brackish salt water, it swirls and churns like the sea. Beneath its darkened waves you can hear the walls of the fallen sailors.","effect":"Fill an entire Zone with water, costs 2 Sanity. For each Zone you fill, apply the Suffocation status to everyone in that Zone and change the Weather there to Severity 4. For every additional 2 Sanity spent, extend the area by 1 Zone."},{"number":2,"name":"The Lost Sailor's Family Values","quote":"\"Once family, always family.\"","description":"Your friends and family look at you differently, it doesn't seem to matter how harsh you are on them. They still just stick around, they may hate you, but they'll never leave you.","effect":"Your Bonds can now reach a negative value of -10 before a Bond is lost. When a Bond is in the negative they aren't exactly friendly or loving but still support you even if they shouldn't."},{"number":3,"name":"The Lost Sailor's Crew","quote":"\"You are captain of a ship in my fleet as vast as the sea.\"","description":"You are transported to the bottom of the sea, you can breathe and move about just as you normally would. You are on a vast ship of fine craftsmanship and manned by a crew of easily 100 members to attend to your every need. Lanterns float float through the sea around you illuminating your vessel.","effect":"Acquire Luxury Housing in the form of a ship in a pocket dimension. The transport process takes 1 hour, if you don't want to wait an hour, it costs 5 Sanity to transport instantly. A CR Easy Memory roll is required to maintain time accuracy; failure results in rolling 1d6 and losing that number of days."}]},{"name":"The Master of Swords","domain":null,"pantheon":"The Beyond","alignment":null,"access":null,"demands":null,"text":"The Master of Swords themselves have no specific culture, weapon, or appearance, clad in battle-worn armor and tattered clothes. They are the embodiment of perfection in combat, a being that has spent eternity mastering the art of violence. Every strike is precise; every battle an opportunity for growth. The Master of Swords only appears in places of combat and is only visible to its followers. They watch every fight, every teaching, every martial practice to refine their own skills. These are the places where their followers may commune and spar with The Master of Swords. However, even a master one day must be replaced, and this entity searches for an apprentice who can defeat them and claim their title. Until then, they continue to perfect the blade, offering followers a path to mastery that can only end in blood.","gifts":[{"number":1,"name":"Master of Sword's Ancient Art","quote":"\"Death should be personal, as should life.\"","description":"You are granted a shrine to place your weapon upon, the shrine itself is made from dark steel and riveted wood with two sculpted hands at the top waiting to hold your weapon. Once you place your weapon on the shrine they fuse together forming a cohesive statue of sorts. A new version of that weapon is created at the base of the shrine and you are now forever dedicated to that weapon.","effect":"Select a melee weapon to master, doubling its Damage. If you use any other weapon or magic, lose 2 Sanity per use."},{"number":2,"name":"Apprenticeship","quote":"\"You have proven worthy, my pupil; come and learn.\"","description":"You now serve as an apprentice under The Master of Swords, being in their mere presence is enough to make you a better fighter. They share a lifetime's worth of experience with you, unlocking aspects of yourself you didn't know existed.","effect":"Choose a second background and apply it to your character, including any Healing Pool adjustments that might need to be made."},{"number":3,"name":"The Master of Sword's Challenge","quote":"\"One day I must be replaced… shall it be you?\".","description":"You have been permitted to enter the Master of Swords personal arena. It is dark and smells of blood and rose petals. Waiting at the other end of the dark stone chamber is an Apprentice adorned in ragged robes and battle-worn armor, their weapon drawn and ready for combat.","effect":"Challenge one of the Master's three apprentices at any time. If you defeat an apprentice, gain a level. Losing results in death; no rolls allowed. Upon defeating all three apprentices, challenge the Master of Swords. If victorious, you become the new Master, gaining +4 in all Aspects and becoming ageless. Your character will now govern The Master of Swords role. If anyone ever takes them as a patron, it will be this character. This character will never die to old age but can still be killed in combat; if that happens, one of the apprentices will take their place.","statBlocks":[{"name":"The Master","type":"Beyond, Dangerous (CR 16)","Body":5,"Mind":4,"Spirit":3,"Health":75,"Sanity":70,"Stability":65,"Attack":"+13","EvadeRating":18,"BodyResistance":14,"MindResistance":14,"SpiritResistance":12,"Speed":8,"Actions":"2 per turn","Modifiers":[{"name":"Blade Mastery","text":"Grants +4 to Attack when using bladed weapons."},{"name":"Counter-attack","text":"When an enemy fails to land a hit, the Apprentice can counter-attack once per turn."},{"name":"Blinding Speed","text":"Adds +2 to Speed and allows the Master to move an additional Zone for free every round."},{"name":"Precision Strike","text":"Allows The Master to ignore 2 BR on every Attack."},{"name":"Warrior's Endurance","text":"Regains 5 Health at the start of each turn."},{"name":"Blade of The Beyond","legendary":true,"text":"If a Critical Attack hits, the Damage dealt is tripled."}]},{"name":"The Apprentice","type":"Beyond, Challenging (CR 16)","Body":3,"Mind":4,"Spirit":2,"Health":40,"Sanity":40,"Stability":35,"Attack":"+9","EvadeRating":14,"BodyResistance":10,"MindResistance":10,"SpiritResistance":8,"Speed":4,"Modifiers":[{"name":"Master of Blades","text":"Grants +3 to Attack when using bladed weapons."},{"name":"Quick Draw","text":"Adds a virtual +3 to your speed for the purposes of determining an Agent’s order in a round."},{"name":"Dueling Stance","text":"Increases Evade Rating (ER) by +2 when fighting a single enemy."},{"name":"Counter-attack","text":"When an enemy fails to land a hit, the Apprentice can counter-attack once per turn."},{"name":"Void Strike","legendary":true,"text":"Converts Damage to Corrupted Damage and ignores all Resistance Types for one Attack per round."}]}]}]},{"name":"The Moon","domain":null,"pantheon":"The Beyond","alignment":null,"access":null,"demands":null,"text":"The Moon longs for the devotion that it believes is rightfully its own, envious of God and all others who hold sway over mortal hearts. It desires to be everything to its followers: god, friend, lover, enemy; there is no limit to the roles it wishes to play. The Moon can see the future, and it offers glimpses to those who pledge themselves fully. Yet despite its knowledge of what is to come, it knows that no matter what it does, it will never have everyone. This unfulfilled craving drives it to seek the total devotion of those who will listen, offering visions and companionship in return. The Moon's followers, in their dreams, are drawn into the Moon Room, a serene white space filled with mirrors and a simple writing desk where they can sit and reflect. It's an intimate place where questions can be asked, and the Moon is always content just to have their company.","gifts":[{"number":1,"name":"The Moon Companion","quote":"\"God, lover, and tormentor... there will be no others, only the Moon.\"","description":"An entity stands beside you as you wake from your encounter with The Moon. It is 10 feet tall, both lanky and voluptuous, and takes the form of whatever gender you desire. Their skin is pale, and they are always interested in conversation. This entity is only visible to you and other Moon worshipers.","effect":"Gain a Wealth Class Advanced Companion. If you communicate with this being around others, they lose 2 Sanity. If you do not communicate with this being, you lose 2 Sanity."},{"number":2,"name":"Visions From The Moon","quote":"\"A glimpse of my power, I share this with you, my precious follower.\"","description":"While in The Moon room, you are able to ponder what life may have next for you. In this process however The Moon will offer a vision of a future event that will come to pass, and help put their followers at ease.","effect":"Once a Mission, you may spend 5 Sanity to ask the Moon for an answer to any question relating to your current tasks. The GM will then provide you with the answer unless it would somehow be game-breaking; in that case, another question may be asked."},{"number":3,"name":"The Chamber of The Moon","quote":"\"Infinite futures, and you can see them all, praise be THE MOON.\"","description":"Gain access to the Moon's Room of Mirrors, where all futures are visible. A reflection of everything that could or will come to pass, every possibility before your eyes and The Moon floating in the center of it all.","effect":"Once in a character's lifetime, you may spend all your Sanity to change an event that happened that day. This can be anything from a character death to losing an artifact. The other event will seem like a distant dream as it is replaced by this new future. This ability should be strong; however, your GM can deny a specific event if it would be game-breaking or ruin a crucial story element."}]},{"name":"The Never Speak","domain":null,"pantheon":"The Beyond","alignment":null,"access":"The Never Speak can never be contacted directly; they are rather stumbled upon in a dream.","demands":"Its followers gain insights into these hidden truths and, in return, must document everything they know before death.","text":"A collector of knowledge, hoarding forbidden and lost secrets in silence. A hunched figure always absorbed in their reading. They have black spots for eyes and a mouth like dripping wax, perfect for resealing scrolls after they finish. The Never Speak gathers all there is to know, regardless of the cost. The Never Speak can never be contacted directly; they are rather stumbled upon in a dream. Like opening a door you don't recognize or falling into a lake, only to wake up in its study. Encounters with The Never Speak could be random or a challenge for knowledge seekers. The Never Speak only communicates with vacant pointing and never looks up from their studies. Its followers gain insights into these hidden truths and, in return, must document everything they know before death.","gifts":[{"number":1,"name":"The Never Speak's Eyes","quote":"\"Make thine eyes like pits and absorb everything.\"","description":"Your eyes sink into your skull, leaving hollow black spots on your face. Even though your eyes seem to be presently missing, you are able to see everything better than you ever could.","effect":"For 1 Sanity per hour, you can choose any type of vision and read any language."},{"number":2,"name":"The Never Speak's Library","quote":"\"Volumes upon volumes of immeasurable knowledge\".","description":"You are transported to a vast library stretching infinitely in all directions. In the center of it all sits The Never Speak; beside him is a register. When you sign your name on the register, the book you were seeking is in your hand as if you had already been holding it.","effect":"Spend 2 Sanity to retrieve a book on anything the character desires."},{"number":3,"name":"The Never Speak's Collection","quote":"\"I bestow upon you my most prized collection; a true scholar such as yourself should have access to only the best books.\"","description":"Your character is given access to The Never Speak's very secret stash of books, which contains everything they have ever recorded.","effect":"When making any IQ roll or Specialized Knowledge roll, you automatically succeed.","attributionNote":"Source text places this Description/Effect block unlabeled/out of order; attributed to this gift by elimination (only gift of the deity lacking description/effect)."}]},{"name":"The Order of the Golden Mask","domain":null,"pantheon":"The Beyond","alignment":null,"access":null,"demands":null,"text":"The Order of the Golden Mask is a welcoming congregation of liches, vampires, and followers of the Great Black Coffin. They believe that if the world cannot be cleansed of its sickness, it should instead be united through rot. The Black Coffin is an oozing, tumorcovered entity filled with a mix of pus, blood, and writhing maggots. Members who choose to step inside are transformed into rotting immortals. These beings are gifted with cancerous mutations that ravage their own flesh, but they also gain the power to spread this affliction to others. The vampires revere them as masters of death, feeding on the blood that endlessly seeps from their palms like a twisted blessing.","gifts":[{"number":1,"name":"The Black Coffin's Blessing","quote":"\"From the Coffin, we are born in glorious death.\"","description":"Upon stepping into the Coffin, your living body dies, and you are reborn in death. Your flesh turns a sickly grey, your features grow gaunt, and your bones protrude beneath decaying skin.","effect":"You gain immortality through cancerous regeneration, becoming immune to death by Health Damage. For 1 Stability, you can inflict cancerous mutations on others, reducing their lifespan by 5 years and dealing 5 Elemental Damage for every Sanity spent. As their bodies decay, your own lifespan increases by 2 years each time you use this ability."},{"number":2,"name":"Ruler of Death","quote":"\"Through rot, we find unity.\"","description":"You extend your bloody hands and summon a vampire servant to cater to your desires. They lap up their new master's succor and bind themselves to you.","effect":"You can now create your own personal undead servant. Summon a vampire servant (Undead Medium, CR 10) who bears the Bloodthirsty Modifier. The rest of the creature's traits are yours to decide. If your servant dies, spend 10 Stability to summon a new one, ensuring your dominion over death remains unbroken."},{"number":3,"name":"Rot","quote":"\"Watch as it all decays.\"","description":"The cancer within you grows stronger, you can feel it feasting upon your body and building itself anew; you have reached the high council and are offered a place among their leaders.","effect":"Undead may no longer harm you in any way and triple the effects of your cancerous mutations for the same amount of Stability. You also now have access to the inner circle of The Order of The Golden Mask, granting access to an Occult Representative who may instantly reveal all 5 memories of Beyond Artifacts or all Modifiers a Monster possesses."}]},{"name":"The Perfumed Host","domain":null,"pantheon":"The Beyond","alignment":null,"access":"Dreaming of The Perfumed Guest is the first step in connecting with them.","demands":null,"text":"A voluptuous, smooth-voiced charmer, The Perfumed Host thrives on the social game, weaving allure and mystery into every interaction. With coy smiles and honeyed words, they play with the hearts of others, guiding them like sheep to their desires. Always accommodating and ever pleasant, turning even the most guarded into willing participants in their emotional dance. Their worshipers are those who desire attention and adoration. Dreaming of The Perfumed Guest is the first step in connecting with them. A pack of sweet, fragrant cigarettes will appear in their hands. When smoked, they are brought to The Dark Parlor, a low-lit room of intimacy and liquor, the perfect place to unwind and chat. The Perfumed Host is always interested in what her guests have to tell her.","gifts":[{"number":1,"name":"The Perfumed Host's Enchantment","quote":"\"I am like a fine wine, dark and intoxicating.\"","description":"Double speak, an open ear, a silver tongue, whatever they want you're here for them; little do they know their playing right into your hand.","effect":"For 1 Sanity per hour, captivate a target, bending their will to your desires. During this time, all they wish to do is please you, fully believing that their actions are their own. This is used to acquire free services of a Wealth Class equal to the amount of Sanity spent.","wealthClassCosts":[{"sanity":1,"wealthClass":"Mundane"},{"sanity":2,"wealthClass":"Quality"},{"sanity":3,"wealthClass":"Advanced"},{"sanity":4,"wealthClass":"Luxury"},{"sanity":5,"wealthClass":"Exotic"}],"bulletsVerbatim":["1 Sanity for Wealth Class Mundane","2 Sanity for Wealth Class Quality","3 Sanity for Wealth Class Advanced","4 Sanity for Wealth Class Luxury","5 Sanity for Wealth Class Exotic"]},{"number":2,"name":"The Perfumed Host's After Party","quote":"\"Whatever they desire, they shall have it; I am always a gracious host.\"","description":"A flash of smoke pours from your body, it fills the lungs of those around you, altering their perception and bending their minds to your will.","effect":"For 5 Sanity, you can project a mass hallucination into the minds of everyone in a Zone for up to 1 hour. Each person sees and hears only what you wish them to, making them believe they are in different realities of your choosing. While under your control, they will act according to the reality you create, unaware of the true world around them. After the effect fades, their memories will be warped, unsure of what was real."},{"number":3,"name":"The Perfumed Host's Diamond","quote":"\"You are everything anyone has ever desired wrapped into a pretty bundle, no one could ever deny you.\"","description":"You have become the epitome of beauty, grace, and charm. There isn't a soul alive that wouldn't do anything for you.","effect":"This character no longer needs to use Spending Power. Instead, they may choose whatever they like as if their Spending Power was unlimited."}]},{"name":"The Thing Between The Walls","domain":null,"pantheon":"The Beyond","alignment":null,"access":"Contacting The Thing Between The Walls is as easy as calling out to it near any crack, crevice, or hall in the world.","demands":"To sustain its endless pursuits, worshipers must provide it with details of all that they see.","text":"A voyeuristic entity comprised of thousands of eyes with a fascination that knows no bounds. People, places, and everything under the sun could be the center of its attention for a time. The Thing Between The Walls delights in watching the lives of others, always searching for something that will sate its curiosity. It peers through cracks and holes, shifting between realities without ever being noticed. Its constant movement is likely responsible for the ruptures that appear in The Beyond, but it cares only for its own curiosity. Those who worship enjoy the thrill of watching the details of life or have an insatiable curiosity to see everything. To sustain its endless pursuits, worshipers must provide it with details of all that they see. Contacting The Thing Between The Walls is as easy as calling out to it near any crack, crevice, or hall in the world.","gifts":[{"number":1,"name":"The Places Between The Walls","quote":"\"So many people to watch, so many lives to voyeuristically live.\"","description":"Your mind melds with the thousands of eyes belonging to The Thing Between The Walls, allowing you to see what they see.","effect":"Watch any place you know of for 1 hour. Costs 4 Sanity."},{"number":2,"name":"Advantageous Details","quote":"\"We know everything about them; we've been watching.\"","description":"You know this place, you know their weakness, you have watched it all.","effect":"Any Monster, person, or place you have observed for over an hour will provide you with a situational bonus when performing actions either in the area or interacting with those Monsters or people."},{"number":3,"name":"Between The Walls are Doors","quote":"\"Walking into a stranger's life is hard, good thing you already got to know them so well.\"","description":"Flashes of all the places and people you've peered at begin to fill your vision. Like a private slideshow of all the things you weren't meant to see, all you have to do is stop on the picture you like best and you'll be there; A dream come true.","effect":"Any place you have watched can now be traveled to. Costs 2 Sanity per person you wish to transport including yourself.","note":"Gift 3 heading lacks a colon in source; description spans a column break."}]}]};
